	}
	targetAttrs := make(map[string]string)
	for _, a := range t.Attr {
		if !isIgnoredAttr(a, opts) {
			targetAttrs[attrID(a)] = a.Value
		}
	}

	// Removed or changed attributes, in base document order.
	for _, a := range b.Attr {
		if isIgnoredAttr(a, opts) {
			continue
		}
		id := attrID(a)
		if tv, ok := targetAttrs[id]; ok {
			if tv != a.Value {
				ops = append(ops, DiffOperation{
					Type:     OpUpdateAttr,
					Path:     path,
					AttrName: id,
					OldValue: a.Value,
					NewValue: tv,
				})
			}
		} else {
			ops = append(ops, DiffOperation{
				Type:     OpRemove,
				Path:     path,
				AttrName: id,
			})
		}
	}

