		} else {
			tUnkeyed = append(tUnkeyed, &keyedChild{"", el, i})
		}
	}

	used := make(map[*Element]bool)
	for _, bi := range bKeyed {
		var matched *keyedChild
		for _, ti := range tKeyed {
			if ti.key == bi.key && !used[ti.el] {
