// patchOp describes a single operation inside a patch document, along with
// the pre-resolved target of its 'sel' attribute.
type patchOp struct {
	node     *Element // the add/remove/replace element
	target   *Element // resolved element for the sel; nil means the document root
	isText   bool     // sel ended with /text()
	isAttr   bool     // sel ended with /@attr
	attrName string   // attribute name when isAttr is true
}

// parsePatchSel splits a patch 'sel' attribute into an element path plus an
// optional /text() or /@attribute suffix.
func parsePatchSel(sel string) (elemPath string, isText, isAttr bool, attrName string) {
	if strings.HasSuffix(sel, "/text()") {
		return sel[:len(sel)-len("/text()")], true, false, ""
	}
	if i := strings.LastIndexByte(sel, '/'); i >= 0 && strings.HasPrefix(sel[i+1:], "@") {
		return sel[:i], false, true, sel[i+2:]
	}
	return sel, false, false, ""
}

// ApplyPatch applies the operations in a patch document to the document 'doc',
// modifying it in place. It returns an error if either document is nil, if
// the patch document is malformed, or if a selection path cannot be resolved.
func ApplyPatch(doc, patch *Document) error {
	if doc == nil || patch == nil {
		return errors.New("etree: document and patch must not be nil")
	}

	root := patch.Root()
	if root == nil || root.Tag != "diff" {
		return errors.New("etree: patch document must have a 'diff' root element")
	}

	// Resolve all targets before any mutation so that earlier operations
	// cannot invalidate the selections of later ones.
	var ops []patchOp
	for _, t := range root.Child {
		el, ok := t.(*Element)
		if !ok {
			continue
		}
		switch el.Tag {
		case "add", "remove", "replace":
		default:
			return fmt.Errorf("etree: unknown patch operation %q", el.Tag)
		}

		var op patchOp
		op.node = el
		sel := el.SelectAttrValue("sel", "")
		elemPath, isText, isAttr, attrName := parsePatchSel(sel)
		op.isText = isText
		op.isAttr = isAttr
		op.attrName = attrName
		if elemPath != "" {
			if tgt := doc.FindElement(elemPath); tgt == nil {
				return fmt.Errorf("etree: patch selection %q does not match any element", sel)
			} else {
				op.target = tgt
			}
		}
		ops = append(ops, op)
	}

	for _, op := range ops {
		if err := applyPatchOp(doc, op); err != nil {
			return err
		}
	}
	return nil
}

// applyPatchOp applies a single resolved patch operation.
func applyPatchOp(doc *Document, op patchOp) error {
	switch op.node.Tag {
	case "add":
		return applyPatchAdd(doc, op)
	case "remove":
		return applyPatchRemove(doc, op)
	case "replace":
		return applyPatchReplace(doc, op)
	default:
		return fmt.Errorf("etree: unknown patch operation %q", op.node.Tag)
	}
}

// applyPatchAdd appends the operation's child elements to the target element,
// or sets an attribute when the operation is an attribute addition.
func applyPatchAdd(doc *Document, op patchOp) error {
	if op.node.SelectAttrValue("type", "") == "attribute" {
		if op.target == nil {
			return errors.New("etree: attribute addition requires a target element")
		}
		name := op.node.SelectAttrValue("name", "")
		if name == "" {
			return errors.New("etree: attribute addition is missing the 'name' attribute")
		}
		setElementAttr(op.target, name, op.node.Text())
		return nil
	}
	for _, c := range op.node.ChildElements() {
		if op.target == nil {
			doc.SetRoot(c.Copy())
		} else {
			op.target.AddChild(c.Copy())
		}
	}
	return nil
}

// applyPatchRemove removes the target element, attribute, or text.
func applyPatchRemove(doc *Document, op patchOp) error {
	switch {
	case op.isText:
		if op.target == nil {
			return errors.New("etree: text removal requires a target element")
		}
		op.target.SetText("")
		return nil
	case op.isAttr:
		if op.target == nil {
			return errors.New("etree: attribute removal requires a target element")
		}
		if op.target.SelectAttr(op.attrName) == nil {
			return fmt.Errorf("etree: attribute %q not found on element at %q", op.attrName, op.node.SelectAttrValue("sel", ""))
		}
		op.target.RemoveAttr(op.attrName)
		return nil
	default:
		if op.target == nil {
			if r := doc.Root(); r != nil {
				doc.RemoveChild(r)
			}
			return nil
		}
		if op.target.Parent() == nil {
			return errors.New("etree: target element is no longer part of the document")
		}
		op.target.Parent().RemoveChild(op.target)
		return nil
	}
}

// applyPatchReplace replaces the target element, attribute, or text.
func applyPatchReplace(doc *Document, op patchOp) error {
	switch {
	case op.isText:
		if op.target == nil {
			return errors.New("etree: text replacement requires a target element")
		}
		op.target.SetText(op.node.Text())
		return nil
	case op.isAttr:
		if op.target == nil {
			return errors.New("etree: attribute replacement requires a target element")
		}
		setElementAttr(op.target, op.attrName, op.node.Text())
		return nil
	default:
		var replacement *Element
		for _, c := range op.node.ChildElements() {
			replacement = c.Copy()
			break
		}
		if replacement == nil {
			// A replace with no content behaves as a removal.
			return applyPatchRemove(doc, op)
		}
		if op.target == nil {
			doc.SetRoot(replacement)
			return nil
		}
		p := op.target.Parent()
		if p == nil {
			return errors.New("etree: target element is no longer part of the document")
		}
		idx := op.target.Index()
		p.RemoveChild(op.target)
		p.InsertChildAt(idx, replacement)
		return nil
	}
}

// setElementAttr sets (or creates) an attribute on the element.
func setElementAttr(e *Element, name, value string) {
	space, key := spaceDecompose(name)
	if a := e.SelectAttr(name); a != nil {
		a.Value = value
		return
	}
	e.addAttr(space, key, value)
}

// ReversePatch creates a new patch document whose operations undo those of
// the provided patch. Additions become removals (attribute additions become
// attribute removals), removals become additions (text removals become
// replacements), and replacements remain replacements. The operations appear
// in reverse order. It returns an error if the patch is nil or malformed.
func ReversePatch(patch *Document) (*Document, error) {
	if patch == nil {
		return nil, errors.New("etree: patch must not be nil")
	}
	root := patch.Root()
	if root == nil || root.Tag != "diff" {
		return nil, errors.New("etree: patch document must have a 'diff' root element")
	}

	doc := NewDocument()
	newRoot := doc.CreateElement("diff")
	newRoot.CreateAttr("xmlns", patchNamespace)

	children := root.ChildElements()
	for i := len(children) - 1; i >= 0; i-- {
		op := children[i]
		switch op.Tag {
		case "add":
			if op.SelectAttrValue("type", "") == "attribute" {
				el := newRoot.CreateElement("remove")
				el.CreateAttr("sel", op.SelectAttrValue("sel", "")+"/@"+op.SelectAttrValue("name", ""))
			} else {
				el := newRoot.CreateElement("remove")
				el.CreateAttr("sel", op.SelectAttrValue("sel", ""))
			}
		case "remove":
			sel := op.SelectAttrValue("sel", "")
			if strings.HasSuffix(sel, "/text()") {
				el := newRoot.CreateElement("replace")
				el.CreateAttr("sel", sel)
				el.SetText("")
			} else {
				el := newRoot.CreateElement("add")
				el.CreateAttr("sel", sel)
			}
		case "replace":
			el := newRoot.CreateElement("replace")
			el.CreateAttr("sel", op.SelectAttrValue("sel", ""))
			for _, c := range op.ChildElements() {
				el.AddChild(c.Copy())
			}
		default:
			return nil, fmt.Errorf("etree: unknown patch operation %q", op.Tag)
		}
	}
	return doc, nil
}
