// DiffSummary aggregates counts of the operations in a diff.
type DiffSummary struct {
	ops []DiffOperation
}

// NewDiffSummary creates a summary of the provided diff operations.
func NewDiffSummary(ops []DiffOperation) *DiffSummary {
	return &DiffSummary{ops: ops}
}

// Additions returns the number of OpAdd operations.
func (s *DiffSummary) Additions() int {
	n := 0
	for _, op := range s.ops {
		if op.Type == OpAdd {
			n++
		}
	}
	return n
}

// Removals returns the number of OpRemove operations.
func (s *DiffSummary) Removals() int {
	n := 0
	for _, op := range s.ops {
		if op.Type == OpRemove {
			n++
		}
	}
	return n
}

// Modifications returns the number of operations that modify existing
// content: OpUpdateText, OpUpdateAttr, and OpReplace operations.
func (s *DiffSummary) Modifications() int {
	n := 0
	for _, op := range s.ops {
		switch op.Type {
		case OpUpdateText, OpUpdateAttr, OpReplace:
			n++
		}
	}
	return n
}

// Moves returns the number of OpMove operations.
func (s *DiffSummary) Moves() int {
	n := 0
	for _, op := range s.ops {
		if op.Type == OpMove {
			n++
		}
	}
	return n
}

// Total returns the total number of operations in the summary.
func (s *DiffSummary) Total() int {
	return len(s.ops)
}

// HasChanges reports whether the summary contains any operations.
func (s *DiffSummary) HasChanges() bool {
	return len(s.ops) > 0
}

// String returns a one-line description of the summary.
func (s *DiffSummary) String() string {
	return fmt.Sprintf("%d additions, %d removals, %d modifications, %d moves",
		s.Additions(), s.Removals(), s.Modifications(), s.Moves())
}

// Resolution selects which side of a conflict wins.
type Resolution int

const (
	// ResolutionOurs keeps the changes from the 'ours' document.
	ResolutionOurs Resolution = iota
	// ResolutionTheirs keeps the changes from the 'theirs' document.
	ResolutionTheirs
	// ResolutionCustom uses a caller-provided value.
	ResolutionCustom
)

// ConflictType describes the kind of a three-way merge conflict.
type ConflictType int

const (
	// ConflictBothModified indicates that both sides modified the same
	// path with the same type of operation but different values.
	ConflictBothModified ConflictType = iota
	// ConflictModifyDelete indicates that one side modified text or an
	// attribute that the other side removed.
	ConflictModifyDelete
	// ConflictStructural indicates that one side removed an element while
	// the other side added or removed content at or under it.
	ConflictStructural
)

// String returns the lower-case name of the conflict type.
func (t ConflictType) String() string {
	switch t {
	case ConflictBothModified:
		return "both-modified"
	case ConflictModifyDelete:
		return "modify-delete"
	case ConflictStructural:
		return "structural"
	default:
		return "unknown"
	}
}

// MergeConflict describes a conflict found during a three-way merge.
type MergeConflict struct {
	// Path is the path of the element the conflict involves.
	Path string
	// BaseValue is the value at the path in the base document.
	BaseValue interface{}
	// OursValue is the value contributed by the 'ours' document.
	OursValue interface{}
	// TheirsValue is the value contributed by the 'theirs' document.
	TheirsValue interface{}
	// Resolution is the value selected when the conflict is resolved.
	Resolution interface{}
	// Type is the kind of conflict.
	Type ConflictType
	// Resolved reports whether the conflict has been resolved.
	Resolved bool
}

// Resolve marks the conflict as resolved, setting Resolution to the value
// of the 'ours' side, the 'theirs' side, or 'customValue', depending on the
// provided resolution.
func (c *MergeConflict) Resolve(resolution Resolution, customValue interface{}) {
	switch resolution {
	case ResolutionOurs:
		c.Resolution = c.OursValue
	case ResolutionTheirs:
		c.Resolution = c.TheirsValue
	default:
		c.Resolution = customValue
	}
	c.Resolved = true
}

// MergeOptions configures the behavior of the Merge3Way function.
type MergeOptions struct {
	// DefaultResolution is used to resolve conflicts when AutoResolve is
	// true.
	DefaultResolution Resolution
	// AutoResolve indicates that conflicts should be resolved
	// automatically using DefaultResolution, with the winning side's
	// changes applied to the merged document.
	AutoResolve bool
}

// DefaultMergeOptions returns a MergeOptions record with default settings:
// conflicts favor 'ours' and are not resolved automatically.
func DefaultMergeOptions() MergeOptions {
	return MergeOptions{
		DefaultResolution: ResolutionOurs,
		AutoResolve:       false,
	}
}
