// opRelation classifies the relationship between an 'ours' operation and a
// 'theirs' operation encountered during a three-way merge.
type opRelation int

const (
	relIndependent opRelation = iota // no interaction; both may apply
	relSame                          // identical effect; apply once
	relConflict                      // a conflict must be reported
)

// isElementDestructive reports whether the operation removes or replaces a
// whole element (as opposed to an attribute).
func isElementDestructive(op DiffOperation) bool {
	return op.AttrName == "" && (op.Type == OpRemove || op.Type == OpReplace)
}

// isContentModification reports whether the operation modifies text or an
// attribute value.
func isContentModification(op DiffOperation) bool {
	return op.Type == OpUpdateText || op.Type == OpUpdateAttr
}

// opValuesEqual reports whether two operations carry equal values.
func opValuesEqual(o, t DiffOperation) bool {
	switch o.Type {
	case OpAdd, OpReplace, OpMove:
		oe, _ := o.NewValue.(*Element)
		te, _ := t.NewValue.(*Element)
		return ElementsDeepEqual(oe, te) && o.Path == t.Path && o.OldPath == t.OldPath
	case OpUpdateText, OpUpdateAttr:
		return newValueString(o.NewValue) == newValueString(t.NewValue)
	default:
		return true
	}
}

// opRelationOf classifies the relationship between the two operations. The
// returned conflictType is only meaningful when the relation is relConflict.
func opRelationOf(o, t DiffOperation) (opRelation, ConflictType) {
	// Same type and target.
	if o.Type == t.Type && o.Path == t.Path && o.AttrName == t.AttrName {
		switch o.Type {
		case OpAdd:
			if opValuesEqual(o, t) {
				return relSame, 0
			}
			// Different additions to the same parent are compatible.
			return relIndependent, 0
		case OpRemove:
			return relSame, 0
		default:
			if opValuesEqual(o, t) {
				return relSame, 0
			}
			return relConflict, ConflictBothModified
		}
	}

	do := isElementDestructive(o)
	dt := isElementDestructive(t)

	if do && dt {
		// One side replaces while the other removes, or one side removes
		// an element the other removes part of.
		if o.Path == t.Path || isUnderPath(o.Path, t.Path) || isUnderPath(t.Path, o.Path) {
			return relConflict, ConflictStructural
		}
		return relIndependent, 0
	}

	if do {
		switch {
		case t.Type == OpAdd && t.Path == o.Path:
			return relConflict, ConflictStructural
		case t.Type == OpRemove && t.AttrName == "" && isUnderPath(t.Path, o.Path):
			return relConflict, ConflictStructural
		case isContentModification(t) && isUnderPath(t.Path, o.Path):
			return relConflict, ConflictModifyDelete
		}
		return relIndependent, 0
	}

	if dt {
		switch {
		case o.Type == OpAdd && o.Path == t.Path:
			return relConflict, ConflictStructural
		case o.Type == OpRemove && o.AttrName == "" && isUnderPath(o.Path, t.Path):
			return relConflict, ConflictStructural
		case isContentModification(o) && isUnderPath(o.Path, t.Path):
			return relConflict, ConflictModifyDelete
		}
		return relIndependent, 0
	}

	// Attribute removal versus modification of the same attribute.
	if o.AttrName != "" && t.AttrName != "" && o.Path == t.Path &&
		o.AttrName == t.AttrName &&
		(o.Type == OpRemove || t.Type == OpRemove) {
		return relConflict, ConflictModifyDelete
	}

	return relIndependent, 0
}

// elementAtBasePath returns the base document's element at 'path', or nil.
func elementAtBasePath(base *Document, path string) *Element {
	if path == "" {
		return base.Root()
	}
	return base.FindElement(path)
}

// buildMergeConflict assembles a MergeConflict record from the two
// conflicting operations.
func buildMergeConflict(base *Document, o, t DiffOperation, ctype ConflictType) *MergeConflict {
	c := &MergeConflict{Type: ctype}

	switch ctype {
	case ConflictStructural:
		if isElementDestructive(o) {
			c.Path = o.Path
		} else {
			c.Path = t.Path
		}
		c.BaseValue = elementAtBasePath(base, c.Path)
		if isElementDestructive(o) {
			c.OursValue = nil
		} else {
			c.OursValue = o.NewValue
		}
		if isElementDestructive(t) {
			c.TheirsValue = nil
		} else {
			c.TheirsValue = t.NewValue
		}
	case ConflictModifyDelete:
		if isContentModification(o) {
			c.Path = o.Path
			if o.Type == OpUpdateAttr {
				c.Path = o.Path + "/@" + o.AttrName
			}
			c.OursValue = o.NewValue
			c.TheirsValue = nil
		} else {
			c.Path = t.Path
			if t.Type == OpUpdateAttr {
				c.Path = t.Path + "/@" + t.AttrName
			}
			c.OursValue = nil
			c.TheirsValue = t.NewValue
		}
		c.BaseValue = valueAtPath(base, c.Path, o, t)
	case ConflictBothModified:
		c.Path = o.Path
		switch o.Type {
		case OpUpdateText:
			c.BaseValue = baseTextAt(base, o.Path)
			c.OursValue = o.NewValue
			c.TheirsValue = t.NewValue
		case OpUpdateAttr:
			c.BaseValue = baseAttrAt(base, o.Path, o.AttrName)
			c.OursValue = o.NewValue
			c.TheirsValue = t.NewValue
		case OpReplace:
			c.BaseValue = elementAtBasePath(base, o.Path)
			c.OursValue = o.NewValue
			c.TheirsValue = t.NewValue
		case OpMove:
			c.BaseValue = elementAtBasePath(base, o.OldPath)
			c.OursValue = o.NewPath
			c.TheirsValue = t.NewPath
		}
	}
	return c
}

// baseTextAt returns the text of the element at 'path' in the base document.
func baseTextAt(base *Document, path string) string {
	if e := elementAtBasePath(base, path); e != nil {
		return e.Text()
	}
	return ""
}

// baseAttrAt returns the value of the named attribute on the element at
// 'path' in the base document. It returns nil when the attribute is absent.
func baseAttrAt(base *Document, path, name string) interface{} {
	e := elementAtBasePath(base, path)
	if e == nil {
		return nil
	}
	if a := e.SelectAttr(name); a != nil {
		return a.Value
	}
	return nil
}

// valueAtPath returns the base document's value for a path that may point to
// an element, an element's text, or an attribute.
func valueAtPath(base *Document, path string, o, t DiffOperation) interface{} {
	if e, i := strings.CutSuffix(path, "/text()"); e != path {
		return baseTextAt(base, e)
	}
	if e, name, ok := strings.Cut(path, "/@"); ok {
		return baseAttrAt(base, e, name)
	}
	if isContentModification(o) || isContentModification(t) {
		// The path names the element whose text or attribute is in play.
		other := t
		if isContentModification(t) {
			other = o
		}
		if other.Type == OpUpdateAttr {
			return baseAttrAt(base, path, other.AttrName)
		}
		return baseTextAt(base, path)
	}
	return elementAtBasePath(base, path)
}

// Merge3Way merges the 'ours' and 'theirs' documents relative to the common
// 'base' document. It returns the merged document, the list of conflicts
// that were found, and any error encountered. All three input documents must
// be non-nil.
//
// Non-conflicting changes from both sides are applied to a copy of the base
// document. Conflicts are reported in the returned list; when
// MergeOptions.AutoResolve is true, each conflict is resolved using
// MergeOptions.DefaultResolution, the winning side's changes are applied to
// the merged document, and the conflict's Resolved flag is set.
func Merge3Way(base, ours, theirs *Document, opts MergeOptions) (*Document, []MergeConflict, error) {
	if base == nil || ours == nil || theirs == nil {
		return nil, nil, errors.New("etree: base, ours, and theirs documents must not be nil")
	}

	dopts := DefaultDiffOptions()
	opsOurs, err := Diff(base, ours, dopts)
	if err != nil {
		return nil, nil, err
	}
	opsTheirs, err := Diff(base, theirs, dopts)
	if err != nil {
		return nil, nil, err
	}

	merged := base.Copy()
	var conflicts []MergeConflict
	var applyOps []DiffOperation
	used := make([]bool, len(opsTheirs))

	for _, o := range opsOurs {
		matched := -1
		var conflict *MergeConflict
		for i, t := range opsTheirs {
			if used[i] {
				continue
			}
			rel, ctype := opRelationOf(o, t)
			switch rel {
			case relSame:
				used[i] = true
				applyOps = append(applyOps, o)
				matched = i
			case relConflict:
				used[i] = true
				conflict = buildMergeConflict(base, o, t, ctype)
				matched = i
			}
			if matched >= 0 {
				break
			}
		}

		if matched < 0 {
			applyOps = append(applyOps, o)
			continue
		}
		if conflict == nil {
			continue
		}

		if opts.AutoResolve {
			conflict.Resolve(opts.DefaultResolution, nil)
			if opts.DefaultResolution == ResolutionTheirs {
				applyOps = append(applyOps, opsTheirs[matched])
			} else if opts.DefaultResolution == ResolutionOurs {
				applyOps = append(applyOps, o)
			}
			// ResolutionCustom without a value applies no change.
		}
		conflicts = append(conflicts, *conflict)
	}

	for i, t := range opsTheirs {
		if !used[i] {
			applyOps = append(applyOps, t)
		}
	}

	if len(applyOps) > 0 {
		if err := ApplyPatch(merged, GeneratePatch(applyOps)); err != nil {
			return nil, nil, err
		}
	}

	if merged.Metadata == nil {
		merged.Metadata = make(map[string]string, 3)
	}
	merged.Metadata["merge.base"] = rootTagName(base)
	merged.Metadata["merge.ours"] = rootTagName(ours)
	merged.Metadata["merge.theirs"] = rootTagName(theirs)

	return merged, conflicts, nil
}

// rootTagName returns the tag of the document's root element, or an empty
// string when the document has no root.
func rootTagName(d *Document) string {
	if d == nil {
		return ""
	}
	if r := d.Root(); r != nil {
		return r.Tag
	}
	return ""
}

// Diff compares the receiver document with 'other' using the provided
// options, returning the list of operations that transform the receiver
// into 'other'.
func (d *Document) Diff(other *Document, opts DiffOptions) ([]DiffOperation, error) {
	return Diff(d, other, opts)
}

// Patch applies the operations in 'patch' to the receiver document.
func (d *Document) Patch(patch *Document) error {
	return ApplyPatch(d, patch)
}

// Merge3Way merges 'ours' and 'theirs' relative to the receiver document,
// which serves as the base.
func (d *Document) Merge3Way(ours, theirs *Document, opts MergeOptions) (*Document, []MergeConflict, error) {
	return Merge3Way(d, ours, theirs, opts)
}
