func TestElementDeepEqual(t *testing.T) {
	// two nil elements are equal
	checkBoolEq(t, ElementsDeepEqual(nil, nil), true)

	a := NewElement("item")
	a.CreateAttr("id", "1")
	a.SetText("hello")
	child := a.CreateElement("sub")
	child.SetText("x")

	b := NewElement("item")
	b.CreateAttr("id", "1")
	b.SetText("hello")
	child2 := b.CreateElement("sub")
	child2.SetText("x")

	checkBoolEq(t, a.DeepEqual(b), true)
	checkBoolEq(t, ElementsDeepEqual(a, b), true)
	checkBoolEq(t, b.DeepEqual(a), true)

	// nil vs non-nil
	checkBoolEq(t, a.DeepEqual(nil), false)
	checkBoolEq(t, (nil *Element).DeepEqual(a), false)
	checkBoolEq(t, ElementsDeepEqual(a, nil), false)
	checkBoolEq(t, ElementsDeepEqual(nil, a), false)

	// tag difference
	c := NewElement("other")
	checkBoolEq(t, a.DeepEqual(c), false)

	// attribute difference
	d := NewElement("item")
	d.CreateAttr("id", "2")
	d.SetText("hello")
	checkBoolEq(t, a.DeepEqual(d), false)

	// attribute order should not matter
	e := NewElement("item")
	e.SetText("hello")
	e.CreateAttr("id", "1")
	checkBoolEq(t, a.DeepEqual(e), true)

	// text difference
	f := NewElement("item")
	f.CreateAttr("id", "1")
	f.SetText("bye")
	checkBoolEq(t, a.DeepEqual(f), false)

	// child difference
	g := NewElement("item")
	g.CreateAttr("id", "1")
	g.SetText("hello")
	gc := g.CreateElement("sub")
	gc.SetText("y")
