	theirs := newDocumentFromString(t, `<root><item id="1">theirs</item></root>`)

	merged, conflicts, err := Merge3Way(base, ours, theirs, DefaultMergeOptions())
	if err != nil {
		t.Fatal(err)
	}
	checkIntEq(t, len(conflicts), 1)
	c := conflicts[0]
	checkStrEq(t, c.Type.String(), "both-modified")
	checkStrEq(t, c.Path, "/root/item[1]")
	checkBoolEq(t, c.Resolved, false)
	checkStrEq(t, c.BaseValue.(string), "base")
	checkStrEq(t, c.OursValue.(string), "ours")
	checkStrEq(t, c.TheirsValue.(string), "theirs")

	// without auto-resolve, base value remains
	got, _ := merged.WriteToString()
	checkStrEq(t, got, `<root><item id="1">base</item></root>`)

	// resolve to ours
	c.Resolve(ResolutionOurs, nil)
	checkBoolEq(t, c.Resolved, true)
	checkStrEq(t, c.Resolution.(string), "ours")

	// resolve to theirs
	c.Resolve(ResolutionTheirs, nil)
	checkStrEq(t, c.Resolution.(string), "theirs")

	// custom
	c.Resolve(ResolutionCustom, "custom")
	checkStrEq(t, c.Resolution.(string), "custom")
