package etree

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"strconv"
	"strings"
)

/*
This file provides XML diffing and patching services for etree. Documents
are compared with the Diff function, which returns a list of DiffOperation
objects describing the differences. Patches are XML documents generated with
GeneratePatch and applied with ApplyPatch. Three documents can be merged
with Merge3Way, which reports conflicts that cannot be resolved
automatically.
*/

// OpType is an enumeration describing the type of a diff operation.
type OpType int

const (
	// OpAdd indicates that an element was added.
	OpAdd OpType = iota
	// OpRemove indicates that an element (or attribute) was removed.
	OpRemove
	// OpReplace indicates that an element was replaced.
	OpReplace
	// OpMove indicates that an element changed position within its parent.
	OpMove
	// OpUpdateAttr indicates that an attribute was added or changed.
	OpUpdateAttr
	// OpUpdateText indicates that an element's text was changed.
	OpUpdateText
)

// String returns the lower-case name of the operation type.
func (t OpType) String() string {
	switch t {
	case OpAdd:
		return "add"
	case OpRemove:
		return "remove"
	case OpReplace:
		return "replace"
	case OpMove:
		return "move"
	case OpUpdateAttr:
		return "update-attr"
	case OpUpdateText:
		return "update-text"
	default:
		return "unknown"
	}
}

// DiffOperation describes a single difference between two XML documents.
type DiffOperation struct {
	// Type is the type of the operation.
	Type OpType
	// Path is the path of the element the operation applies to. For OpAdd,
	// the path is that of the parent element that receives the new child.
	Path string
	// OldPath is the original path of a moved element (OpMove).
	OldPath string
	// NewPath is the new path of a moved element (OpMove).
	NewPath string
	// AttrName is the name of the attribute an OpUpdateAttr or
	// attribute OpRemove applies to.
	AttrName string
	// OldValue is the value before the operation. For OpUpdateText and
	// OpUpdateAttr, it holds the previous string value (nil when the
	// attribute did not previously exist).
	OldValue interface{}
	// NewValue is the value after the operation. For OpAdd, OpReplace and
	// OpMove, it holds the *Element involved; for OpUpdateText and
	// OpUpdateAttr, it holds the new string value.
	NewValue interface{}
}

// String returns a human-readable description of the operation.
func (op DiffOperation) String() string {
	switch op.Type {
	case OpMove:
		return "MOVE " + op.OldPath + " -> " + op.Path
	case OpUpdateAttr:
		return "UPDATE-ATTR " + op.Path + " @" + op.AttrName
	default:
		return strings.ToUpper(op.Type.String()) + " " + op.Path
	}
}

// IdentityMode determines how corresponding elements are matched between
// the base and target documents during a diff.
type IdentityMode int

const (
	// IdentityPosition matches elements by their position (index) among
	// their parent's children.
	IdentityPosition IdentityMode = iota
	// IdentityKeyAttribute matches elements by the value of a key
	// attribute, as declared in DiffOptions.KeyAttributes. The element tag
	// is not part of the matching key.
	IdentityKeyAttribute
	// IdentityContentHash matches elements by a hash of their content.
	IdentityContentHash
)

// DiffOptions configures the behavior of the Diff function.
type DiffOptions struct {
	// IdentityMode determines how corresponding elements are matched.
	IdentityMode IdentityMode
	// KeyAttributes maps an element tag to the name of the attribute that
	// identifies it, when IdentityMode is IdentityKeyAttribute.

