// elementPath returns the absolute path of the element, using positional
// predicates (one-based index among same-tagged siblings) for every
// element below the root. For example, the second 'item' child of the root
// element yields '/root/item[2]'.
func elementPath(e *Element) string {
	if e == nil || e.Tag == "" {
		return ""
	}

	chain := make([]*Element, 0, 8)
	for seg := e; seg != nil && seg.Tag != ""; seg = seg.Parent() {
		chain = append(chain, seg)
	}

	// Reverse the chain so the root element appears first.
	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
		chain[i], chain[j] = chain[j], chain[i]
	}

	parts := make([]string, 0, len(chain))
	for i, seg := range chain {
		part := seg.FullTag()
		if i > 0 {
			part += "[" + strconv.Itoa(sameTagSiblingIndex(seg)+1) + "]"
		}
		parts = append(parts, part)
	}
	return "/" + strings.Join(parts, "/")
