+func TestElementDeepEqual(t *testing.T) {
+	// two nil elements are equal
+	checkBoolEq(t, ElementsDeepEqual(nil, nil), true)
+
+	a := NewElement("item")
+	a.CreateAttr("id", "1")
+	a.SetText("hello")
+	child := a.CreateElement("sub")
+	child.SetText("x")
+
+	b := NewElement("item")
+	b.CreateAttr("id", "1")
+	b.SetText("hello")
+	child2 := b.CreateElement("sub")
+	child2.SetText("x")
+
+	checkBoolEq(t, a.DeepEqual(b), true)
+	checkBoolEq(t, ElementsDeepEqual(a, b), true)
+	checkBoolEq(t, b.DeepEqual(a), true)
+
+	// nil vs non-nil
+	var nilEl *Element
+	checkBoolEq(t, nilEl.DeepEqual(a), false)
+	checkBoolEq(t, ElementsDeepEqual(a, nil), false)
+	checkBoolEq(t, ElementsDeepEqual(nil, a), false)
+
+	// tag difference
+	c := NewElement("other")
+	checkBoolEq(t, a.DeepEqual(c), false)
+
+	// attribute difference
+	d := NewElement("item")
+	d.CreateAttr("id", "2")
+	d.SetText("hello")
+	checkBoolEq(t, a.DeepEqual(d), false)
+
+	// attribute order should not matter
+	e := NewElement("item")
+	e.SetText("hello")
+	e.CreateAttr("id", "1")
+	ec := e.CreateElement("sub")
+	ec.SetText("x")
+	checkBoolEq(t, a.DeepEqual(e), true)
+
+	// text difference
+	f := NewElement("item")
+	f.CreateAttr("id", "1")
+	f.SetText("bye")
+	checkBoolEq(t, a.DeepEqual(f), false)
+
+	// child difference
+	g := NewElement("item")
+	g.CreateAttr("id", "1")
+	g.SetText("hello")
+	gc := g.CreateElement("sub")
+	gc.SetText("y")
+	checkBoolEq(t, a.DeepEqual(g), false)
+
+	// namespace difference
+	h := NewElement("ns:item")
+	h.CreateAttr("id", "1")
+	h.SetText("hello")
+	hc := h.CreateElement("sub")
+	hc.SetText("x")
+	checkBoolEq(t, a.DeepEqual(h), false)
