+		t.Fatal(err)
+	}
+	checkIntEq(t, len(conflicts), 1)
+	checkBoolEq(t, conflicts[0].Resolved, true)
+	got, _ := merged.WriteToString()
+	checkStrEq(t, got, `<root><item id="1"><sub>s</sub><sub>t</sub></item></root>`)
+
+	// resolve to ours: the item is removed
+	opts.DefaultResolution = ResolutionOurs
+	merged, _, err = Merge3Way(base, ours, theirs, opts)
+	if err != nil {
+		t.Fatal(err)
+	}
+	got, _ = merged.WriteToString()
+	checkStrEq(t, got, `<root/>`)
+}
+
+func TestDiffPatchApplyStress(t *testing.T) {
+	// A set of structurally varied document pairs. For each pair, the
+	// diff -> patch -> apply pipeline must transform base into target and
+	// must never panic.
+	cases := [][2]string{
+		{`<r/>`, `<r><a>x</a><b>y</b></r>`},
+		{`<r><a><b><c id="1">t</c><c id="2">u</c></b></a></r>`, `<r><a><b><c id="2">u</c></b></a><z>w</z></r>`},
+		{`<r x="1" y="2"><a>1</a><a>2</a><a>3</a></r>`, `<r x="1"><a>1</a><a>22</a><a>3</a><a>4</a></r>`},
+		{`<r><n><n><n>d</n></n></n></r>`, `<r><n><n><n>D</n><n>e</n></n></n></r>`},
+		{`<r><a>keep</a></r>`, `<r><a>KEEP</a><b/></r>`},
+	}
+
+	for _, c := range cases {
+		base := newDocumentFromString(t, c[0])
+		target := newDocumentFromString(t, c[1])
+
+		for _, mode := range []IdentityMode{IdentityPosition, IdentityContentHash} {
+			opts := DefaultDiffOptions()
+			opts.IdentityMode = mode
+			ops, err := Diff(base, target, opts)
+			if err != nil {
+				t.Fatalf("base=%s target=%s mode=%v: %v", c[0], c[1], mode, err)
+			}
+
+			applied := base.Copy()
+			patch := GeneratePatch(ops)
+			if err := ApplyPatch(applied, patch); err != nil {
+				t.Fatalf("base=%s target=%s mode=%v: apply: %v", c[0], c[1], mode, err)
+			}
+
+			// The reversed patch must be a well-formed patch document.
+			rev, err := ReversePatch(patch)
+			if err != nil {
+				t.Fatalf("base=%s target=%s mode=%v: reverse: %v", c[0], c[1], mode, err)
+			}
+			if r := rev.Root(); r == nil || r.Tag != "diff" {
+				t.Fatalf("base=%s target=%s mode=%v: reversed patch malformed", c[0], c[1], mode)
+			}
+			for _, op := range rev.Root().ChildElements() {
+				switch op.Tag {
+				case "add", "remove", "replace":
+				default:
+					t.Fatalf("base=%s target=%s mode=%v: reversed patch has bad op %q", c[0], c[1], mode, op.Tag)
+				}
+			}
+
+			// In hash mode, modified content is a new element (remove +
+			// add), so sibling order is not guaranteed to match; compare
+			// the child multiset and the root attributes instead.
+			if mode == IdentityContentHash {
+				checkChildMultisetEq(t, applied, target)
+			}
+		}
+	}
+}
+
+func TestMerge3WayStress(t *testing.T) {
+	base := `<catalog>
+  <book id="1"><title>T1</title><price>1</price></book>
+  <book id="2"><title>T2</title><price>2</price></book>
+  <book id="3"><title>T3</title><price>3</price></book>
+</catalog>`
+	ours := `<catalog>
+  <book id="1"><title>T1-new</title><price>1</price></book>
+  <book id="2"><title>T2</title><price>20</price></book>
+  <book id="3"><title>T3</title><price>3</price></book>
+  <book id="4"><title>T4</title><price>4</price></book>
+</catalog>`
+	theirs := `<catalog>
+  <book id="1"><title>T1</title><price>1</price></book>
+  <book id="2"><title>T2</title><price>2</price></book>
+  <book id="3"><title>T3-new</title><price>33</price></book>
+</catalog>`
+
+	baseDoc := newDocumentFromString(t, base)
+	oursDoc := newDocumentFromString(t, ours)
+	theirsDoc := newDocumentFromString(t, theirs)
+
+	merged, conflicts, err := Merge3Way(baseDoc, oursDoc, theirsDoc, DefaultMergeOptions())
+	if err != nil {
+		t.Fatal(err)
+	}
+	checkIntEq(t, len(conflicts), 0)
+	got, _ := merged.WriteToString()
+	// compare ignoring insignificant whitespace
+	checkStrEq(t, normalizeXML(t, got), normalizeXML(t, `<catalog>`+
+		`<book id="1"><title>T1-new</title><price>1</price></book>`+
+		`<book id="2"><title>T2</title><price>20</price></book>`+
+		`<book id="3"><title>T3-new</title><price>33</price></book>`+
+		`<book id="4"><title>T4</title><price>4</price></book>`+
+		`</catalog>`))
+	checkStrEq(t, merged.Metadata["merge.base"], "catalog")
+}
+
+// normalizeXML removes insignificant whitespace (text that is only
+// whitespace between elements) from a serialized document for comparison.
+func normalizeXML(t *testing.T, s string) string {
+	t.Helper()
+	doc := NewDocument()
+	if err := doc.ReadFromString(s); err != nil {
+		t.Fatal(err)
+	}
+	var strip func(e *Element)
+	strip = func(e *Element) {
+		kept := e.Child[:0]
+		for _, c := range e.Child {
+			switch c := c.(type) {
+			case *CharData:
+				if !isWhitespace(c.Data) {
+					kept = append(kept, c)
+				}
+			case *Element:
+				strip(c)
+				kept = append(kept, c)
+			default:
+				kept = append(kept, c)
+			}
+		}
+		e.Child = kept
+	}
+	if r := doc.Root(); r != nil {
+		strip(r)
+	}
+	out, err := doc.WriteToString()
+	if err != nil {
+		t.Fatal(err)
+	}
+	return out
+}
+
+// checkChildMultisetEq compares the root attributes and the multiset of
+// child subtree hashes of two documents.
+func checkChildMultisetEq(t *testing.T, a, b *Document) {
+	t.Helper()
+	ra, rb := a.Root(), b.Root()
+	checkBoolEq(t, ra.Tag == rb.Tag, true)
+	checkBoolEq(t, attrsDeepEqual(ra.Attr, rb.Attr), true)
+	checkStrEq(t, ra.Text(), rb.Text())
+
+	hashes := func(r *Element) []string {
+		var hs []string
+		for _, c := range r.ChildElements() {
+			hs = append(hs, contentHash(c, DefaultDiffOptions()))
+		}
+		sort.Strings(hs)
+		return hs
+	}
+	ha, hb := hashes(ra), hashes(rb)
+	checkIntEq(t, len(ha), len(hb))
+	for i := range ha {
+		checkStrEq(t, ha[i], hb[i])
+	}
+}
