diff --git a/diff.go b/diff.go
new file mode 100644
index 0000000..58cda92
--- /dev/null
+++ b/diff.go
@@ -0,0 +1,1601 @@
+// Copyright 2015-2019 Brett Vickers.
+// Use of this source code is governed by a BSD-style
+// license that can be found in the LICENSE file.
+
+package etree
+
+import (
+	"crypto/sha256"
+	"encoding/hex"
+	"errors"
+	"fmt"
+	"strconv"
+	"strings"
+)
+
+/*
+This file provides XML diffing and patching services for etree. Documents
+are compared with the Diff function, which returns a list of DiffOperation
+objects describing the differences. Patches are XML documents generated with
+GeneratePatch and applied with ApplyPatch. Three documents can be merged
+with Merge3Way, which reports conflicts that cannot be resolved
+automatically.
+*/
+
+// OpType is an enumeration describing the type of a diff operation.
+type OpType int
+
+const (
+	// OpAdd indicates that an element was added.
+	OpAdd OpType = iota
+	// OpRemove indicates that an element (or attribute) was removed.
+	OpRemove
+	// OpReplace indicates that an element was replaced.
+	OpReplace
+	// OpMove indicates that an element changed position within its parent.
+	OpMove
+	// OpUpdateAttr indicates that an attribute was added or changed.
+	OpUpdateAttr
+	// OpUpdateText indicates that an element's text was changed.
+	OpUpdateText
+)
+
+// String returns the lower-case name of the operation type.
+func (t OpType) String() string {
+	switch t {
+	case OpAdd:
+		return "add"
+	case OpRemove:
+		return "remove"
+	case OpReplace:
+		return "replace"
+	case OpMove:
+		return "move"
+	case OpUpdateAttr:
+		return "update-attr"
+	case OpUpdateText:
+		return "update-text"
+	default:
+		return "unknown"
+	}
+}
+
+// DiffOperation describes a single difference between two XML documents.
+type DiffOperation struct {
+	// Type is the type of the operation.
+	Type OpType
+	// Path is the path of the element the operation applies to. For OpAdd,
+	// the path is that of the parent element that receives the new child.
+	Path string
+	// OldPath is the original path of a moved element (OpMove).
+	OldPath string
+	// NewPath is the new path of a moved element (OpMove).
+	NewPath string
+	// AttrName is the name of the attribute an OpUpdateAttr or
+	// attribute OpRemove applies to.
+	AttrName string
+	// OldValue is the value before the operation. For OpUpdateText and
+	// OpUpdateAttr, it holds the previous string value (nil when the
+	// attribute did not previously exist).
+	OldValue interface{}
+	// NewValue is the value after the operation. For OpAdd, OpReplace and
+	// OpMove, it holds the *Element involved; for OpUpdateText and
+	// OpUpdateAttr, it holds the new string value.
+	NewValue interface{}
+}
+
+// String returns a human-readable description of the operation.
+func (op DiffOperation) String() string {
+	switch op.Type {
+	case OpMove:
+		return "MOVE " + op.OldPath + " -> " + op.Path
+	case OpUpdateAttr:
+		return "UPDATE-ATTR " + op.Path + " @" + op.AttrName
+	default:
+		return strings.ToUpper(op.Type.String()) + " " + op.Path
+	}
+}
+
+// IdentityMode determines how corresponding elements are matched between
+// the base and target documents during a diff.
+type IdentityMode int
+
+const (
+	// IdentityPosition matches elements by their position (index) among
+	// their parent's children.
+	IdentityPosition IdentityMode = iota
+	// IdentityKeyAttribute matches elements by the value of a key
+	// attribute, as declared in DiffOptions.KeyAttributes. The element tag
+	// is not part of the matching key.
+	IdentityKeyAttribute
+	// IdentityContentHash matches elements by a hash of their content.
+	IdentityContentHash
+)
+
+// DiffOptions configures the behavior of the Diff function.
+type DiffOptions struct {
+	// IdentityMode determines how corresponding elements are matched.
+	IdentityMode IdentityMode
+	// KeyAttributes maps an element tag to the name of the attribute that
+	// identifies it, when IdentityMode is IdentityKeyAttribute.
+	KeyAttributes map[string]string
+	// IgnoreAttrs lists attribute names to exclude from comparison.
+	IgnoreAttrs []string
+	// IgnoreWhitespace indicates that whitespace differences in text
+	// content should be ignored.
+	IgnoreWhitespace bool
+	// IgnoreOrder indicates that the order of sibling elements should not
+	// be treated as significant.
+	IgnoreOrder bool
+}
+
+// DefaultDiffOptions returns a DiffOptions record with default settings:
+// positional identity, no key attributes, whitespace ignored, and order
+// significant.
+func DefaultDiffOptions() DiffOptions {
+	return DiffOptions{
+		IdentityMode:     IdentityPosition,
+		KeyAttributes:    nil,
+		IgnoreWhitespace: true,
+		IgnoreOrder:      false,
+	}
+}
+
+// elementPath returns the absolute path of the element, using positional
+// predicates (one-based index among same-tagged siblings) for every
+// element below the root. For example, the second 'item' child of the root
+// element yields '/root/item[2]'.
+func elementPath(e *Element) string {
+	if e == nil || e.Tag == "" {
+		return ""
+	}
+
+	chain := make([]*Element, 0, 8)
+	for seg := e; seg != nil && seg.Tag != ""; seg = seg.Parent() {
+		chain = append(chain, seg)
+	}
+
+	// Reverse the chain so the root element appears first.
+	for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
+		chain[i], chain[j] = chain[j], chain[i]
+	}
+
+	parts := make([]string, 0, len(chain))
+	for i, seg := range chain {
+		part := seg.FullTag()
+		if i > 0 {
+			part += "[" + strconv.Itoa(sameTagSiblingIndex(seg)+1) + "]"
+		}
+		parts = append(parts, part)
+	}
+	return "/" + strings.Join(parts, "/")
+}
+
+// sameTagSiblingIndex returns the zero-based position of the element among
+// its siblings that share the same space and tag.
+func sameTagSiblingIndex(e *Element) int {
+	if e.parent == nil {
+		return 0
+	}
+	n := 0
+	for _, c := range e.parent.Child {
+		if ce, ok := c.(*Element); ok && ce.Space == e.Space && ce.Tag == e.Tag {
+			if ce == e {
+				return n
+			}
+			n++
+		}
+	}
+	return n
+}
+
+// parentPath returns the path of the parent of the element at 'path', or an
+// empty string if the element is the document root.
+func parentPath(path string) string {
+	i := strings.LastIndexByte(path, '/')
+	if i <= 0 {
+		return ""
+	}
+	return path[:i]
+}
+
+// isUnderPath reports whether path 'p' is the same as, or a descendant of,
+// path 'parent'.
+func isUnderPath(p, parent string) bool {
+	if parent == "" {
+		return p == ""
+	}
+	if p == parent {
+		return true
+	}
+	return strings.HasPrefix(p, parent+"/")
+}
+
+// attrID returns the space:key identifier of an attribute.
+func attrID(a Attr) string {
+	if a.Space == "" {
+		return a.Key
+	}
+	return a.Space + ":" + a.Key
+}
+
+// isIgnoredAttr reports whether the attribute is excluded from comparison
+// by the provided options.
+func isIgnoredAttr(a Attr, opts DiffOptions) bool {
+	for _, name := range opts.IgnoreAttrs {
+		if name == a.Key || name == attrID(a) {
+			return true
+		}
+	}
+	return false
+}
+
+// normalizeText collapses internal whitespace and trims the ends of the
+// string.
+func normalizeText(s string) string {
+	return strings.Join(strings.Fields(s), " ")
+}
+
+// diffTextValue returns the text of an element, normalized when the options
+// request whitespace to be ignored.
+func diffTextValue(e *Element, opts DiffOptions) string {
+	t := e.Text()
+	if opts.IgnoreWhitespace {
+		t = normalizeText(t)
+	}
+	return t
+}
+
+// contentHash returns a hash of the element's content, excluding ignored
+// attributes and (when requested) whitespace, including all descendants.
+func contentHash(e *Element, opts DiffOptions) string {
+	h := sha256.New()
+	h.Write([]byte(e.FullTag()))
+	for _, a := range e.Attr {
+		if isIgnoredAttr(a, opts) {
+			continue
+		}
+		h.Write([]byte(attrID(a)))
+		h.Write([]byte{0})
+		h.Write([]byte(a.Value))
+		h.Write([]byte{0})
+	}
+	h.Write([]byte(diffTextValue(e, opts)))
+	for _, c := range e.ChildElements() {
+		h.Write([]byte(contentHash(c, opts)))
+	}
+	return hex.EncodeToString(h.Sum(nil))
+}
+
+// Diff compares the base and target documents and returns a list of
+// operations that, when applied to the base document, transform it into the
+// target document. It returns an error if either document is nil.
+func Diff(base, target *Document, opts DiffOptions) ([]DiffOperation, error) {
+	if base == nil || target == nil {
+		return nil, errors.New("etree: base and target documents must not be nil")
+	}
+
+	baseRoot := base.Root()
+	targetRoot := target.Root()
+
+	if baseRoot == nil && targetRoot == nil {
+		return nil, nil
+	}
+	if baseRoot == nil {
+		return []DiffOperation{
+			{Type: OpAdd, Path: "", NewValue: targetRoot},
+		}, nil
+	}
+	if targetRoot == nil {
+		return []DiffOperation{
+			{Type: OpRemove, Path: "/" + baseRoot.FullTag()},
+		}, nil
+	}
+
+	if baseRoot.FullTag() != targetRoot.FullTag() {
+		return []DiffOperation{
+			{Type: OpReplace, Path: "/" + baseRoot.FullTag(), NewValue: targetRoot},
+		}, nil
+	}
+
+	return diffElements(baseRoot, targetRoot, "/"+baseRoot.FullTag(), opts), nil
+}
+
+// diffElements compares two matched elements and returns the operations
+// describing the differences between them. 'path' is the path of the base
+// element.
+func diffElements(b, t *Element, path string, opts DiffOptions) []DiffOperation {
+	if b.FullTag() != t.FullTag() {
+		return []DiffOperation{
+			{Type: OpReplace, Path: path, NewValue: t},
+		}
+	}
+
+	var ops []DiffOperation
+	ops = append(ops, diffAttributes(b, t, path, opts)...)
+	ops = append(ops, diffText(b, t, path, opts)...)
+	ops = append(ops, diffChildren(b, t, path, opts)...)
+	return ops
+}
+
+// diffAttributes returns operations describing attribute differences.
+func diffAttributes(b, t *Element, path string, opts DiffOptions) []DiffOperation {
+	var ops []DiffOperation
+
+	baseAttrs := make(map[string]string)
+	for _, a := range b.Attr {
+		if !isIgnoredAttr(a, opts) {
+			baseAttrs[attrID(a)] = a.Value
+		}
+	}
+	targetAttrs := make(map[string]string)
+	for _, a := range t.Attr {
+		if !isIgnoredAttr(a, opts) {
+			targetAttrs[attrID(a)] = a.Value
+		}
+	}
+
+	// Removed or changed attributes, in base document order.
+	for _, a := range b.Attr {
+		if isIgnoredAttr(a, opts) {
+			continue
+		}
+		id := attrID(a)
+		if tv, ok := targetAttrs[id]; ok {
+			if tv != a.Value {
+				ops = append(ops, DiffOperation{
+					Type:     OpUpdateAttr,
+					Path:     path,
+					AttrName: id,
+					OldValue: a.Value,
+					NewValue: tv,
+				})
+			}
+		} else {
+			ops = append(ops, DiffOperation{
+				Type:     OpRemove,
+				Path:     path,
+				AttrName: id,
+			})
+		}
+	}
+
+	// Added attributes, in target document order.
+	for _, a := range t.Attr {
+		if isIgnoredAttr(a, opts) {
+			continue
+		}
+		if _, ok := baseAttrs[attrID(a)]; !ok {
+			ops = append(ops, DiffOperation{
+				Type:     OpUpdateAttr,
+				Path:     path,
+				AttrName: attrID(a),
+				OldValue: nil,
+				NewValue: a.Value,
+			})
+		}
+	}
+	return ops
+}
+
+// diffText returns an operation when the text content differs.
+func diffText(b, t *Element, path string, opts DiffOptions) []DiffOperation {
+	bt := diffTextValue(b, opts)
+	tt := diffTextValue(t, opts)
+	if bt != tt {
+		return []DiffOperation{
+			{Type: OpUpdateText, Path: path, OldValue: bt, NewValue: tt},
+		}
+	}
+	return nil
+}
+
+// diffChildren returns operations describing differences between the child
+// element lists of the two elements.
+func diffChildren(b, t *Element, path string, opts DiffOptions) []DiffOperation {
+	bc := b.ChildElements()
+	tc := t.ChildElements()
+
+	switch opts.IdentityMode {
+	case IdentityKeyAttribute:
+		return diffChildrenKeyed(b, t, bc, tc, path, opts)
+	case IdentityContentHash:
+		return diffChildrenHashed(bc, tc, path, opts)
+	default:
+		if opts.IgnoreOrder {
+			return diffChildrenUnordered(bc, tc, path, opts)
+		}
+		return diffChildrenIndexed(bc, tc, path, opts)
+	}
+}
+
+// diffChildrenIndexed pairs children by their index within the parent.
+func diffChildrenIndexed(bc, tc []*Element, path string, opts DiffOptions) []DiffOperation {
+	var ops []DiffOperation
+
+	n := len(bc)
+	if len(tc) < n {
+		n = len(tc)
+	}
+	for i := 0; i < n; i++ {
+		ops = append(ops, diffElements(bc[i], tc[i], elementPath(bc[i]), opts)...)
+	}
+	for i := n; i < len(bc); i++ {
+		ops = append(ops, DiffOperation{Type: OpRemove, Path: elementPath(bc[i])})
+	}
+	for i := n; i < len(tc); i++ {
+		ops = append(ops, DiffOperation{Type: OpAdd, Path: path, NewValue: tc[i]})
+	}
+	return ops
+}
+
+// diffChildrenHashed pairs children by a hash of their content, ignoring
+// sibling order.
+func diffChildrenHashed(bc, tc []*Element, path string, opts DiffOptions) []DiffOperation {
+	var ops []DiffOperation
+
+	type item struct {
+		hash string
+		el   *Element
+	}
+	bitems := make([]item, 0, len(bc))
+	for _, el := range bc {
+		bitems = append(bitems, item{contentHash(el, opts), el})
+	}
+	titems := make([]item, 0, len(tc))
+	for _, el := range tc {
+		titems = append(titems, item{contentHash(el, opts), el})
+	}
+
+	used := make(map[*Element]bool)
+	for _, bi := range bitems {
+		var matched *Element
+		for _, ti := range titems {
+			if ti.hash == bi.hash && !used[ti.el] {
+				matched = ti.el
+				break
+			}
+		}
+		if matched == nil {
+			ops = append(ops, DiffOperation{Type: OpRemove, Path: elementPath(bi.el)})
+		} else {
+			used[matched] = true
+		}
+	}
+	for _, ti := range titems {
+		if !used[ti.el] {
+			ops = append(ops, DiffOperation{Type: OpAdd, Path: path, NewValue: ti.el})
+		}
+	}
+	return ops
+}
+
+// keyedChild describes a child element and its position within the parent's
+// child element list.
+type keyedChild struct {
+	key string
+	el  *Element
+	idx int
+}
+
+// childKey returns the identity key of the element, based on the options'
+// KeyAttributes map. The second return value reports whether the element is
+// keyed at all. The element tag is deliberately not part of the key, so
+// elements with different tags but the same key value are paired together.
+func childKey(el *Element, opts DiffOptions) (string, bool) {
+	if opts.KeyAttributes == nil {
+		return "", false
+	}
+	attrName, ok := opts.KeyAttributes[el.FullTag()]
+	if !ok {
+		return "", false
+	}
+	a := el.SelectAttr(attrName)
+	if a == nil {
+		return "", false
+	}
+	return a.Value, true
+}
+
+// diffChildrenKeyed pairs children by key attribute value.
+func diffChildrenKeyed(b, t *Element, bc, tc []*Element, path string, opts DiffOptions) []DiffOperation {
+	var ops []DiffOperation
+
+	var bKeyed, tKeyed, bUnkeyed, tUnkeyed []*keyedChild
+	for i, el := range bc {
+		if k, ok := childKey(el, opts); ok {
+			bKeyed = append(bKeyed, &keyedChild{k, el, i})
+		} else {
+			bUnkeyed = append(bUnkeyed, &keyedChild{"", el, i})
+		}
+	}
+	for i, el := range tc {
+		if k, ok := childKey(el, opts); ok {
+			tKeyed = append(tKeyed, &keyedChild{k, el, i})
+		} else {
+			tUnkeyed = append(tUnkeyed, &keyedChild{"", el, i})
+		}
+	}
+
+	used := make(map[*Element]bool)
+	for _, bi := range bKeyed {
+		var matched *keyedChild
+		for _, ti := range tKeyed {
+			if ti.key == bi.key && !used[ti.el] {
+				matched = ti
+				break
+			}
+		}
+		if matched == nil {
+			ops = append(ops, DiffOperation{Type: OpRemove, Path: elementPath(bi.el)})
+		} else {
+			used[matched.el] = true
+			if bi.idx != matched.idx && !opts.IgnoreOrder {
+				ops = append(ops, DiffOperation{
+					Type:     OpMove,
+					Path:     elementPath(matched.el),
+					OldPath:  elementPath(bi.el),
+					NewPath:  elementPath(matched.el),
+					NewValue: matched.el,
+				})
+			} else {
+				ops = append(ops, diffElements(bi.el, matched.el, elementPath(bi.el), opts)...)
+			}
+		}
+	}
+	for _, ti := range tKeyed {
+		if !used[ti.el] {
+			ops = append(ops, DiffOperation{Type: OpAdd, Path: path, NewValue: ti.el})
+		}
+	}
+
+	if opts.IgnoreOrder {
+		ops = append(ops, diffChildrenUnorderedList(bUnkeyed, tUnkeyed, path, opts)...)
+	} else {
+		ops = append(ops, diffChildrenIndexedList(bUnkeyed, tUnkeyed, path, opts)...)
+	}
+	return ops
+}
+
+// diffChildrenUnorderedList is the ordered-independent diff over a list of
+// keyedChild records.
+func diffChildrenUnorderedList(bList, tList []*keyedChild, path string, opts DiffOptions) []DiffOperation {
+	bc := make([]*Element, 0, len(bList))
+	for _, c := range bList {
+		bc = append(bc, c.el)
+	}
+	tc := make([]*Element, 0, len(tList))
+	for _, c := range tList {
+		tc = append(tc, c.el)
+	}
+	return diffChildrenUnordered(bc, tc, path, opts)
+}
+
+// diffChildrenUnordered pairs children while ignoring sibling order.
+// Children with identical content (hash) are matched first; remaining
+// children with the same tag are paired by their index within the tag group
+// so that modifications are reported instead of a removal plus an addition.
+func diffChildrenUnordered(bc, tc []*Element, path string, opts DiffOptions) []DiffOperation {
+	var ops []DiffOperation
+
+	type item struct {
+		hash string
+		el   *Element
+	}
+	bitems := make([]item, 0, len(bc))
+	for _, el := range bc {
+		bitems = append(bitems, item{contentHash(el, opts), el})
+	}
+	titems := make([]item, 0, len(tc))
+	for _, el := range tc {
+		titems = append(titems, item{contentHash(el, opts), el})
+	}
+
+	// Exact content matches, regardless of position.
+	usedT := make(map[*Element]bool)
+	var bUnmatched []*Element
+	for _, bi := range bitems {
+		var matched *Element
+		for _, ti := range titems {
+			if ti.hash == bi.hash && !usedT[ti.el] {
+				matched = ti.el
+				break
+			}
+		}
+		if matched == nil {
+			bUnmatched = append(bUnmatched, bi.el)
+		} else {
+			usedT[matched] = true
+		}
+	}
+	var tUnmatched []*Element
+	for _, ti := range titems {
+		if !usedT[ti.el] {
+			tUnmatched = append(tUnmatched, ti.el)
+		}
+	}
+
+	// Group the unmatched children by tag so that modified siblings of the
+	// same tag can be paired for a detailed diff.
+	bGroups := make(map[string][]*Element)
+	var bOrder []string
+	for _, el := range bUnmatched {
+		tag := el.FullTag()
+		if _, ok := bGroups[tag]; !ok {
+			bOrder = append(bOrder, tag)
+		}
+		bGroups[tag] = append(bGroups[tag], el)
+	}
+	tGroups := make(map[string][]*Element)
+	var tOrder []string
+	for _, el := range tUnmatched {
+		tag := el.FullTag()
+		if _, ok := tGroups[tag]; !ok {
+			tOrder = append(tOrder, tag)
+		}
+		tGroups[tag] = append(tGroups[tag], el)
+	}
+
+	usedTG := make(map[*Element]bool)
+	for _, tag := range bOrder {
+		bg := bGroups[tag]
+		tg := tGroups[tag]
+		n := len(bg)
+		if len(tg) < n {
+			n = len(tg)
+		}
+		for i := 0; i < n; i++ {
+			usedTG[tg[i]] = true
+			ops = append(ops, diffElements(bg[i], tg[i], elementPath(bg[i]), opts)...)
+		}
+		for i := n; i < len(bg); i++ {
+			ops = append(ops, DiffOperation{Type: OpRemove, Path: elementPath(bg[i])})
+		}
+	}
+	for _, tag := range tOrder {
+		for _, el := range tGroups[tag] {
+			if !usedTG[el] {
+				ops = append(ops, DiffOperation{Type: OpAdd, Path: path, NewValue: el})
+			}
+		}
+	}
+	return ops
+}
+
+// diffChildrenIndexedList pairs unkeyed children by index.
+func diffChildrenIndexedList(bList, tList []*keyedChild, path string, opts DiffOptions) []DiffOperation {
+	bc := make([]*Element, 0, len(bList))
+	for _, c := range bList {
+		bc = append(bc, c.el)
+	}
+	tc := make([]*Element, 0, len(tList))
+	for _, c := range tList {
+		tc = append(tc, c.el)
+	}
+	return diffChildrenIndexed(bc, tc, path, opts)
+}
+
+// DeepEqual reports whether the element and 'other' are structurally
+// equivalent, comparing tags, namespaces, attributes, text, and children
+// recursively. Two nil elements are considered equal; a nil element and a
+// non-nil element are not.
+func (e *Element) DeepEqual(other *Element) bool {
+	if e == nil && other == nil {
+		return true
+	}
+	if e == nil || other == nil {
+		return false
+	}
+	if e.Space != other.Space || e.Tag != other.Tag {
+		return false
+	}
+	if !attrsDeepEqual(e.Attr, other.Attr) {
+		return false
+	}
+	if len(e.Child) != len(other.Child) {
+		return false
+	}
+	for i := range e.Child {
+		if !tokenDeepEqual(e.Child[i], other.Child[i]) {
+			return false
+		}
+	}
+	return true
+}
+
+// ElementsDeepEqual reports whether elements 'a' and 'b' are structurally
+// equivalent. It is safe to call with nil arguments: two nil elements are
+// equal, while a nil element and a non-nil element are not.
+func ElementsDeepEqual(a, b *Element) bool {
+	if a == nil || b == nil {
+		return a == b
+	}
+	return a.DeepEqual(b)
+}
+
+// attrsDeepEqual reports whether two attribute lists contain the same set of
+// space:key/value triples, regardless of order.
+func attrsDeepEqual(a, b []Attr) bool {
+	if len(a) != len(b) {
+		return false
+	}
+	count := func(list []Attr) map[string]int {
+		m := make(map[string]int, len(list))
+		for _, at := range list {
+			m[attrID(at)+"\x00"+at.Value]++
+		}
+		return m
+	}
+	ca, cb := count(a), count(b)
+	if len(ca) != len(cb) {
+		return false
+	}
+	for k, v := range ca {
+		if cb[k] != v {
+			return false
+		}
+	}
+	return true
+}
+
+// tokenDeepEqual reports whether two child tokens are structurally
+// equivalent.
+func tokenDeepEqual(a, b Token) bool {
+	if a == nil || b == nil {
+		return a == b
+	}
+	switch ta := a.(type) {
+	case *Element:
+		tb, ok := b.(*Element)
+		if !ok {
+			return false
+		}
+		return ta.DeepEqual(tb)
+	case *CharData:
+		tb, ok := b.(*CharData)
+		if !ok {
+			return false
+		}
+		return ta.Data == tb.Data
+	case *Comment:
+		tb, ok := b.(*Comment)
+		if !ok {
+			return false
+		}
+		return ta.Data == tb.Data
+	case *Directive:
+		tb, ok := b.(*Directive)
+		if !ok {
+			return false
+		}
+		return ta.Data == tb.Data
+	case *ProcInst:
+		tb, ok := b.(*ProcInst)
+		if !ok {
+			return false
+		}
+		return ta.Target == tb.Target && ta.Inst == tb.Inst
+	default:
+		return false
+	}
+}
+
+// patchNamespace is the XML namespace declared by patch documents.
+const patchNamespace = "urn:ietf:params:xml:ns:patch-ops"
+
+// newValueString converts an operation's value to a string for inclusion in
+// a patch document.
+func newValueString(v interface{}) string {
+	switch s := v.(type) {
+	case string:
+		return s
+	case nil:
+		return ""
+	default:
+		return fmt.Sprintf("%v", s)
+	}
+}
+
+// GeneratePatch creates a patch document from a list of diff operations. The
+// patch document's root element is 'diff', in the namespace
+// urn:ietf:params:xml:ns:patch-ops, containing one 'add', 'remove', or
+// 'replace' element per operation. Element selections are expressed as XPath
+// strings with positional predicates in the 'sel' attribute.
+func GeneratePatch(ops []DiffOperation) *Document {
+	doc := NewDocument()
+	root := doc.CreateElement("diff")
+	root.CreateAttr("xmlns", patchNamespace)
+
+	for _, op := range ops {
+		switch op.Type {
+		case OpAdd:
+			el := root.CreateElement("add")
+			el.CreateAttr("sel", op.Path)
+			if e, ok := op.NewValue.(*Element); ok && e != nil {
+				el.AddChild(e.Copy())
+			}
+		case OpRemove:
+			el := root.CreateElement("remove")
+			sel := op.Path
+			if op.AttrName != "" {
+				sel += "/@" + op.AttrName
+			}
+			el.CreateAttr("sel", sel)
+		case OpReplace:
+			el := root.CreateElement("replace")
+			el.CreateAttr("sel", op.Path)
+			if e, ok := op.NewValue.(*Element); ok && e != nil {
+				el.AddChild(e.Copy())
+			}
+		case OpUpdateAttr:
+			switch op.OldValue.(type) {
+			case nil:
+				el := root.CreateElement("add")
+				el.CreateAttr("sel", op.Path)
+				el.CreateAttr("type", "attribute")
+				el.CreateAttr("name", op.AttrName)
+				el.SetText(newValueString(op.NewValue))
+			default:
+				el := root.CreateElement("replace")
+				el.CreateAttr("sel", op.Path+"/@"+op.AttrName)
+				el.SetText(newValueString(op.NewValue))
+			}
+		case OpUpdateText:
+			el := root.CreateElement("replace")
+			el.CreateAttr("sel", op.Path+"/text()")
+			el.SetText(newValueString(op.NewValue))
+		case OpMove:
+			el := root.CreateElement("remove")
+			el.CreateAttr("sel", op.OldPath)
+			if e, ok := op.NewValue.(*Element); ok && e != nil {
+				add := root.CreateElement("add")
+				add.CreateAttr("sel", parentPath(op.Path))
+				add.AddChild(e.Copy())
+			}
+		}
+	}
+	return doc
+}
+
+// patchOp describes a single operation inside a patch document, along with
+// the pre-resolved target of its 'sel' attribute.
+type patchOp struct {
+	node     *Element // the add/remove/replace element
+	target   *Element // resolved element for the sel; nil means the document root
+	isText   bool     // sel ended with /text()
+	isAttr   bool     // sel ended with /@attr
+	attrName string   // attribute name when isAttr is true
+}
+
+// parsePatchSel splits a patch 'sel' attribute into an element path plus an
+// optional /text() or /@attribute suffix.
+func parsePatchSel(sel string) (elemPath string, isText, isAttr bool, attrName string) {
+	if strings.HasSuffix(sel, "/text()") {
+		return sel[:len(sel)-len("/text()")], true, false, ""
+	}
+	if i := strings.LastIndexByte(sel, '/'); i >= 0 && strings.HasPrefix(sel[i+1:], "@") {
+		return sel[:i], false, true, sel[i+2:]
+	}
+	return sel, false, false, ""
+}
+
+// ApplyPatch applies the operations in a patch document to the document 'doc',
+// modifying it in place. It returns an error if either document is nil, if
+// the patch document is malformed, or if a selection path cannot be resolved.
+func ApplyPatch(doc, patch *Document) error {
+	if doc == nil || patch == nil {
+		return errors.New("etree: document and patch must not be nil")
+	}
+
+	root := patch.Root()
+	if root == nil || root.Tag != "diff" {
+		return errors.New("etree: patch document must have a 'diff' root element")
+	}
+
+	// Resolve all targets before any mutation so that earlier operations
+	// cannot invalidate the selections of later ones.
+	var ops []patchOp
+	for _, t := range root.Child {
+		el, ok := t.(*Element)
+		if !ok {
+			continue
+		}
+		switch el.Tag {
+		case "add", "remove", "replace":
+		default:
+			return fmt.Errorf("etree: unknown patch operation %q", el.Tag)
+		}
+
+		var op patchOp
+		op.node = el
+		sel := el.SelectAttrValue("sel", "")
+		elemPath, isText, isAttr, attrName := parsePatchSel(sel)
+		op.isText = isText
+		op.isAttr = isAttr
+		op.attrName = attrName
+		if elemPath != "" {
+			if tgt := doc.FindElement(elemPath); tgt == nil {
+				return fmt.Errorf("etree: patch selection %q does not match any element", sel)
+			} else {
+				op.target = tgt
+			}
+		}
+		ops = append(ops, op)
+	}
+
+	for _, op := range ops {
+		if err := applyPatchOp(doc, op); err != nil {
+			return err
+		}
+	}
+	return nil
+}
+
+// applyPatchOp applies a single resolved patch operation.
+func applyPatchOp(doc *Document, op patchOp) error {
+	switch op.node.Tag {
+	case "add":
+		return applyPatchAdd(doc, op)
+	case "remove":
+		return applyPatchRemove(doc, op)
+	case "replace":
+		return applyPatchReplace(doc, op)
+	default:
+		return fmt.Errorf("etree: unknown patch operation %q", op.node.Tag)
+	}
+}
+
+// applyPatchAdd appends the operation's child elements to the target element,
+// or sets an attribute when the operation is an attribute addition.
+func applyPatchAdd(doc *Document, op patchOp) error {
+	if op.node.SelectAttrValue("type", "") == "attribute" {
+		if op.target == nil {
+			return errors.New("etree: attribute addition requires a target element")
+		}
+		name := op.node.SelectAttrValue("name", "")
+		if name == "" {
+			return errors.New("etree: attribute addition is missing the 'name' attribute")
+		}
+		setElementAttr(op.target, name, op.node.Text())
+		return nil
+	}
+	for _, c := range op.node.ChildElements() {
+		if op.target == nil {
+			doc.SetRoot(c.Copy())
+		} else {
+			op.target.AddChild(c.Copy())
+		}
+	}
+	return nil
+}
+
+// applyPatchRemove removes the target element, attribute, or text.
+func applyPatchRemove(doc *Document, op patchOp) error {
+	switch {
+	case op.isText:
+		if op.target == nil {
+			return errors.New("etree: text removal requires a target element")
+		}
+		op.target.SetText("")
+		return nil
+	case op.isAttr:
+		if op.target == nil {
+			return errors.New("etree: attribute removal requires a target element")
+		}
+		if op.target.SelectAttr(op.attrName) == nil {
+			return fmt.Errorf("etree: attribute %q not found on element at %q", op.attrName, op.node.SelectAttrValue("sel", ""))
+		}
+		op.target.RemoveAttr(op.attrName)
+		return nil
+	default:
+		if op.target == nil {
+			if r := doc.Root(); r != nil {
+				doc.RemoveChild(r)
+			}
+			return nil
+		}
+		if op.target.Parent() == nil {
+			return errors.New("etree: target element is no longer part of the document")
+		}
+		op.target.Parent().RemoveChild(op.target)
+		return nil
+	}
+}
+
+// applyPatchReplace replaces the target element, attribute, or text.
+func applyPatchReplace(doc *Document, op patchOp) error {
+	switch {
+	case op.isText:
+		if op.target == nil {
+			return errors.New("etree: text replacement requires a target element")
+		}
+		op.target.SetText(op.node.Text())
+		return nil
+	case op.isAttr:
+		if op.target == nil {
+			return errors.New("etree: attribute replacement requires a target element")
+		}
+		setElementAttr(op.target, op.attrName, op.node.Text())
+		return nil
+	default:
+		var replacement *Element
+		for _, c := range op.node.ChildElements() {
+			replacement = c.Copy()
+			break
+		}
+		if replacement == nil {
+			// A replace with no content behaves as a removal.
+			return applyPatchRemove(doc, op)
+		}
+		if op.target == nil {
+			doc.SetRoot(replacement)
+			return nil
+		}
+		p := op.target.Parent()
+		if p == nil {
+			return errors.New("etree: target element is no longer part of the document")
+		}
+		idx := op.target.Index()
+		p.RemoveChild(op.target)
+		p.InsertChildAt(idx, replacement)
+		return nil
+	}
+}
+
+// setElementAttr sets (or creates) an attribute on the element.
+func setElementAttr(e *Element, name, value string) {
+	space, key := spaceDecompose(name)
+	if a := e.SelectAttr(name); a != nil {
+		a.Value = value
+		return
+	}
+	e.addAttr(space, key, value)
+}
+
+// ReversePatch creates a new patch document whose operations undo those of
+// the provided patch. Additions become removals (attribute additions become
+// attribute removals), removals become additions (text removals become
+// replacements), and replacements remain replacements. The operations appear
+// in reverse order. It returns an error if the patch is nil or malformed.
+func ReversePatch(patch *Document) (*Document, error) {
+	if patch == nil {
+		return nil, errors.New("etree: patch must not be nil")
+	}
+	root := patch.Root()
+	if root == nil || root.Tag != "diff" {
+		return nil, errors.New("etree: patch document must have a 'diff' root element")
+	}
+
+	doc := NewDocument()
+	newRoot := doc.CreateElement("diff")
+	newRoot.CreateAttr("xmlns", patchNamespace)
+
+	children := root.ChildElements()
+	for i := len(children) - 1; i >= 0; i-- {
+		op := children[i]
+		switch op.Tag {
+		case "add":
+			if op.SelectAttrValue("type", "") == "attribute" {
+				el := newRoot.CreateElement("remove")
+				el.CreateAttr("sel", op.SelectAttrValue("sel", "")+"/@"+op.SelectAttrValue("name", ""))
+			} else {
+				el := newRoot.CreateElement("remove")
+				el.CreateAttr("sel", op.SelectAttrValue("sel", ""))
+			}
+		case "remove":
+			sel := op.SelectAttrValue("sel", "")
+			if strings.HasSuffix(sel, "/text()") {
+				el := newRoot.CreateElement("replace")
+				el.CreateAttr("sel", sel)
+				el.SetText("")
+			} else {
+				el := newRoot.CreateElement("add")
+				el.CreateAttr("sel", sel)
+			}
+		case "replace":
+			el := newRoot.CreateElement("replace")
+			el.CreateAttr("sel", op.SelectAttrValue("sel", ""))
+			for _, c := range op.Child {
+				el.AddChild(c.dup(nil))
+			}
+		default:
+			return nil, fmt.Errorf("etree: unknown patch operation %q", op.Tag)
+		}
+	}
+	return doc, nil
+}
+
+// DiffSummary aggregates counts of the operations in a diff.
+type DiffSummary struct {
+	ops []DiffOperation
+}
+
+// NewDiffSummary creates a summary of the provided diff operations.
+func NewDiffSummary(ops []DiffOperation) *DiffSummary {
+	return &DiffSummary{ops: ops}
+}
+
+// Additions returns the number of OpAdd operations.
+func (s *DiffSummary) Additions() int {
+	n := 0
+	for _, op := range s.ops {
+		if op.Type == OpAdd {
+			n++
+		}
+	}
+	return n
+}
+
+// Removals returns the number of OpRemove operations.
+func (s *DiffSummary) Removals() int {
+	n := 0
+	for _, op := range s.ops {
+		if op.Type == OpRemove {
+			n++
+		}
+	}
+	return n
+}
+
+// Modifications returns the number of operations that modify existing
+// content: OpUpdateText, OpUpdateAttr, and OpReplace operations.
+func (s *DiffSummary) Modifications() int {
+	n := 0
+	for _, op := range s.ops {
+		switch op.Type {
+		case OpUpdateText, OpUpdateAttr, OpReplace:
+			n++
+		}
+	}
+	return n
+}
+
+// Moves returns the number of OpMove operations.
+func (s *DiffSummary) Moves() int {
+	n := 0
+	for _, op := range s.ops {
+		if op.Type == OpMove {
+			n++
+		}
+	}
+	return n
+}
+
+// Total returns the total number of operations in the summary.
+func (s *DiffSummary) Total() int {
+	return len(s.ops)
+}
+
+// HasChanges reports whether the summary contains any operations.
+func (s *DiffSummary) HasChanges() bool {
+	return len(s.ops) > 0
+}
+
+// String returns a one-line description of the summary.
+func (s *DiffSummary) String() string {
+	return fmt.Sprintf("%d additions, %d removals, %d modifications, %d moves",
+		s.Additions(), s.Removals(), s.Modifications(), s.Moves())
+}
+
+// Resolution selects which side of a conflict wins.
+type Resolution int
+
+const (
+	// ResolutionOurs keeps the changes from the 'ours' document.
+	ResolutionOurs Resolution = iota
+	// ResolutionTheirs keeps the changes from the 'theirs' document.
+	ResolutionTheirs
+	// ResolutionCustom uses a caller-provided value.
+	ResolutionCustom
+)
+
+// ConflictType describes the kind of a three-way merge conflict.
+type ConflictType int
+
+const (
+	// ConflictBothModified indicates that both sides modified the same
+	// path with the same type of operation but different values.
+	ConflictBothModified ConflictType = iota
+	// ConflictModifyDelete indicates that one side modified text or an
+	// attribute that the other side removed.
+	ConflictModifyDelete
+	// ConflictStructural indicates that one side removed an element while
+	// the other side added or removed content at or under it.
+	ConflictStructural
+)
+
+// String returns the lower-case name of the conflict type.
+func (t ConflictType) String() string {
+	switch t {
+	case ConflictBothModified:
+		return "both-modified"
+	case ConflictModifyDelete:
+		return "modify-delete"
+	case ConflictStructural:
+		return "structural"
+	default:
+		return "unknown"
+	}
+}
+
+// MergeConflict describes a conflict found during a three-way merge.
+type MergeConflict struct {
+	// Path is the path of the element the conflict involves.
+	Path string
+	// BaseValue is the value at the path in the base document.
+	BaseValue interface{}
+	// OursValue is the value contributed by the 'ours' document.
+	OursValue interface{}
+	// TheirsValue is the value contributed by the 'theirs' document.
+	TheirsValue interface{}
+	// Resolution is the value selected when the conflict is resolved.
+	Resolution interface{}
+	// Type is the kind of conflict.
+	Type ConflictType
+	// Resolved reports whether the conflict has been resolved.
+	Resolved bool
+}
+
+// Resolve marks the conflict as resolved, setting Resolution to the value
+// of the 'ours' side, the 'theirs' side, or 'customValue', depending on the
+// provided resolution.
+func (c *MergeConflict) Resolve(resolution Resolution, customValue interface{}) {
+	switch resolution {
+	case ResolutionOurs:
+		c.Resolution = c.OursValue
+	case ResolutionTheirs:
+		c.Resolution = c.TheirsValue
+	default:
+		c.Resolution = customValue
+	}
+	c.Resolved = true
+}
+
+// MergeOptions configures the behavior of the Merge3Way function.
+type MergeOptions struct {
+	// DefaultResolution is used to resolve conflicts when AutoResolve is
+	// true.
+	DefaultResolution Resolution
+	// AutoResolve indicates that conflicts should be resolved
+	// automatically using DefaultResolution, with the winning side's
+	// changes applied to the merged document.
+	AutoResolve bool
+}
+
+// DefaultMergeOptions returns a MergeOptions record with default settings:
+// conflicts favor 'ours' and are not resolved automatically.
+func DefaultMergeOptions() MergeOptions {
+	return MergeOptions{
+		DefaultResolution: ResolutionOurs,
+		AutoResolve:       false,
+	}
+}
+
+// opRelation classifies the relationship between an 'ours' operation and a
+// 'theirs' operation encountered during a three-way merge.
+type opRelation int
+
+const (
+	relIndependent opRelation = iota // no interaction; both may apply
+	relSame                          // identical effect; apply once
+	relConflict                      // a conflict must be reported
+)
+
+// isElementDestructive reports whether the operation removes or replaces a
+// whole element (as opposed to an attribute).
+func isElementDestructive(op DiffOperation) bool {
+	return op.AttrName == "" && (op.Type == OpRemove || op.Type == OpReplace)
+}
+
+// isContentModification reports whether the operation modifies text or an
+// attribute value.
+func isContentModification(op DiffOperation) bool {
+	return op.Type == OpUpdateText || op.Type == OpUpdateAttr
+}
+
+// opValuesEqual reports whether two operations carry equal values.
+func opValuesEqual(o, t DiffOperation) bool {
+	switch o.Type {
+	case OpAdd, OpReplace, OpMove:
+		oe, _ := o.NewValue.(*Element)
+		te, _ := t.NewValue.(*Element)
+		return ElementsDeepEqual(oe, te) && o.Path == t.Path && o.OldPath == t.OldPath
+	case OpUpdateText, OpUpdateAttr:
+		return newValueString(o.NewValue) == newValueString(t.NewValue)
+	default:
+		return true
+	}
+}
+
+// opRelationOf classifies the relationship between the two operations. The
+// returned conflictType is only meaningful when the relation is relConflict.
+func opRelationOf(o, t DiffOperation) (opRelation, ConflictType) {
+	// Same type and target.
+	if o.Type == t.Type && o.Path == t.Path && o.AttrName == t.AttrName {
+		switch o.Type {
+		case OpAdd:
+			if opValuesEqual(o, t) {
+				return relSame, 0
+			}
+			// Different additions to the same parent are compatible.
+			return relIndependent, 0
+		case OpRemove:
+			return relSame, 0
+		default:
+			if opValuesEqual(o, t) {
+				return relSame, 0
+			}
+			return relConflict, ConflictBothModified
+		}
+	}
+
+	do := isElementDestructive(o)
+	dt := isElementDestructive(t)
+
+	if do && dt {
+		// One side replaces while the other removes, or one side removes
+		// an element the other removes part of.
+		if o.Path == t.Path || isUnderPath(o.Path, t.Path) || isUnderPath(t.Path, o.Path) {
+			return relConflict, ConflictStructural
+		}
+		return relIndependent, 0
+	}
+
+	if do {
+		switch {
+		case t.Type == OpAdd && t.Path == o.Path:
+			return relConflict, ConflictStructural
+		case t.Type == OpRemove && t.AttrName == "" && isUnderPath(t.Path, o.Path):
+			return relConflict, ConflictStructural
+		case isContentModification(t) && isUnderPath(t.Path, o.Path):
+			return relConflict, ConflictModifyDelete
+		}
+		return relIndependent, 0
+	}
+
+	if dt {
+		switch {
+		case o.Type == OpAdd && o.Path == t.Path:
+			return relConflict, ConflictStructural
+		case o.Type == OpRemove && o.AttrName == "" && isUnderPath(o.Path, t.Path):
+			return relConflict, ConflictStructural
+		case isContentModification(o) && isUnderPath(o.Path, t.Path):
+			return relConflict, ConflictModifyDelete
+		}
+		return relIndependent, 0
+	}
+
+	// Attribute removal versus modification of the same attribute.
+	if o.AttrName != "" && t.AttrName != "" && o.Path == t.Path &&
+		o.AttrName == t.AttrName &&
+		(o.Type == OpRemove || t.Type == OpRemove) {
+		return relConflict, ConflictModifyDelete
+	}
+
+	return relIndependent, 0
+}
+
+// elementAtBasePath returns the base document's element at 'path', or nil.
+func elementAtBasePath(base *Document, path string) *Element {
+	if path == "" {
+		return base.Root()
+	}
+	return base.FindElement(path)
+}
+
+// buildMergeConflict assembles a MergeConflict record from the two
+// conflicting operations.
+func buildMergeConflict(base *Document, o, t DiffOperation, ctype ConflictType) *MergeConflict {
+	c := &MergeConflict{Type: ctype}
+
+	switch ctype {
+	case ConflictStructural:
+		if isElementDestructive(o) {
+			c.Path = o.Path
+		} else {
+			c.Path = t.Path
+		}
+		c.BaseValue = elementAtBasePath(base, c.Path)
+		if isElementDestructive(o) {
+			c.OursValue = nil
+		} else {
+			c.OursValue = o.NewValue
+		}
+		if isElementDestructive(t) {
+			c.TheirsValue = nil
+		} else {
+			c.TheirsValue = t.NewValue
+		}
+	case ConflictModifyDelete:
+		if isContentModification(o) {
+			c.Path = o.Path
+			c.OursValue = o.NewValue
+			c.TheirsValue = nil
+			if o.Type == OpUpdateAttr {
+				c.BaseValue = baseAttrAt(base, o.Path, o.AttrName)
+			} else {
+				c.BaseValue = baseTextAt(base, o.Path)
+			}
+		} else {
+			c.Path = t.Path
+			c.OursValue = nil
+			c.TheirsValue = t.NewValue
+			if t.Type == OpUpdateAttr {
+				c.BaseValue = baseAttrAt(base, t.Path, t.AttrName)
+			} else {
+				c.BaseValue = baseTextAt(base, t.Path)
+			}
+		}
+	case ConflictBothModified:
+		c.Path = o.Path
+		switch o.Type {
+		case OpUpdateText:
+			c.BaseValue = baseTextAt(base, o.Path)
+			c.OursValue = o.NewValue
+			c.TheirsValue = t.NewValue
+		case OpUpdateAttr:
+			c.BaseValue = baseAttrAt(base, o.Path, o.AttrName)
+			c.OursValue = o.NewValue
+			c.TheirsValue = t.NewValue
+		case OpReplace:
+			c.BaseValue = elementAtBasePath(base, o.Path)
+			c.OursValue = o.NewValue
+			c.TheirsValue = t.NewValue
+		case OpMove:
+			c.BaseValue = elementAtBasePath(base, o.OldPath)
+			c.OursValue = o.NewPath
+			c.TheirsValue = t.NewPath
+		case OpAdd:
+			c.BaseValue = nil
+			c.OursValue = o.NewValue
+			c.TheirsValue = t.NewValue
+		}
+	}
+	return c
+}
+
+// baseTextAt returns the text of the element at 'path' in the base document.
+func baseTextAt(base *Document, path string) string {
+	if e := elementAtBasePath(base, path); e != nil {
+		return e.Text()
+	}
+	return ""
+}
+
+// baseAttrAt returns the value of the named attribute on the element at
+// 'path' in the base document. It returns nil when the attribute is absent.
+func baseAttrAt(base *Document, path, name string) interface{} {
+	e := elementAtBasePath(base, path)
+	if e == nil {
+		return nil
+	}
+	if a := e.SelectAttr(name); a != nil {
+		return a.Value
+	}
+	return nil
+}
+
+// Merge3Way merges the 'ours' and 'theirs' documents relative to the common
+// 'base' document. It returns the merged document, the list of conflicts
+// that were found, and any error encountered. All three input documents must
+// be non-nil.
+//
+// Non-conflicting changes from both sides are applied to a copy of the base
+// document. Conflicts are reported in the returned list; when
+// MergeOptions.AutoResolve is true, each conflict is resolved using
+// MergeOptions.DefaultResolution, the winning side's changes are applied to
+// the merged document, and the conflict's Resolved flag is set.
+func Merge3Way(base, ours, theirs *Document, opts MergeOptions) (*Document, []MergeConflict, error) {
+	if base == nil || ours == nil || theirs == nil {
+		return nil, nil, errors.New("etree: base, ours, and theirs documents must not be nil")
+	}
+
+	dopts := DefaultDiffOptions()
+	opsOurs, err := Diff(base, ours, dopts)
+	if err != nil {
+		return nil, nil, err
+	}
+	opsTheirs, err := Diff(base, theirs, dopts)
+	if err != nil {
+		return nil, nil, err
+	}
+
+	merged := base.Copy()
+	var conflicts []MergeConflict
+	var applyOps []DiffOperation
+	used := make([]bool, len(opsTheirs))
+
+	for _, o := range opsOurs {
+		matched := -1
+		var conflict *MergeConflict
+		for i, t := range opsTheirs {
+			if used[i] {
+				continue
+			}
+			rel, ctype := opRelationOf(o, t)
+			switch rel {
+			case relSame:
+				used[i] = true
+				applyOps = append(applyOps, o)
+				matched = i
+			case relConflict:
+				used[i] = true
+				conflict = buildMergeConflict(base, o, t, ctype)
+				matched = i
+			}
+			if matched >= 0 {
+				break
+			}
+		}
+
+		if matched < 0 {
+			applyOps = append(applyOps, o)
+			continue
+		}
+		if conflict == nil {
+			continue
+		}
+
+		if opts.AutoResolve {
+			conflict.Resolve(opts.DefaultResolution, nil)
+			if opts.DefaultResolution == ResolutionTheirs {
+				applyOps = append(applyOps, opsTheirs[matched])
+			} else if opts.DefaultResolution == ResolutionOurs {
+				applyOps = append(applyOps, o)
+			}
+			// ResolutionCustom without a value applies no change.
+		}
+		conflicts = append(conflicts, *conflict)
+	}
+
+	for i, t := range opsTheirs {
+		if !used[i] {
+			applyOps = append(applyOps, t)
+		}
+	}
+
+	if len(applyOps) > 0 {
+		if err := ApplyPatch(merged, GeneratePatch(applyOps)); err != nil {
+			return nil, nil, err
+		}
+	}
+
+	if merged.Metadata == nil {
+		merged.Metadata = make(map[string]string, 3)
+	}
+	merged.Metadata["merge.base"] = rootTagName(base)
+	merged.Metadata["merge.ours"] = rootTagName(ours)
+	merged.Metadata["merge.theirs"] = rootTagName(theirs)
+
+	return merged, conflicts, nil
+}
+
+// rootTagName returns the tag of the document's root element, or an empty
+// string when the document has no root.
+func rootTagName(d *Document) string {
+	if d == nil {
+		return ""
+	}
+	if r := d.Root(); r != nil {
+		return r.Tag
+	}
+	return ""
+}
+
+// Diff compares the receiver document with 'other' using the provided
+// options, returning the list of operations that transform the receiver
+// into 'other'.
+func (d *Document) Diff(other *Document, opts DiffOptions) ([]DiffOperation, error) {
+	return Diff(d, other, opts)
+}
+
+// Patch applies the operations in 'patch' to the receiver document.
+func (d *Document) Patch(patch *Document) error {
+	return ApplyPatch(d, patch)
+}
+
+// Merge3Way merges 'ours' and 'theirs' relative to the receiver document,
+// which serves as the base.
+func (d *Document) Merge3Way(ours, theirs *Document, opts MergeOptions) (*Document, []MergeConflict, error) {
+	return Merge3Way(d, ours, theirs, opts)
+}
