+func TestDiffNilDocuments(t *testing.T) {
+	if _, err := Diff(nil, NewDocument(), DefaultDiffOptions()); err == nil {
+		t.Error("etree: expected error for nil base document")
+	}
+	if _, err := Diff(NewDocument(), nil, DefaultDiffOptions()); err == nil {
+		t.Error("etree: expected error for nil target document")
+	}
+}
+
+func TestDiffIdenticalDocuments(t *testing.T) {
+	ops, err := Diff(
+		newDocumentFromString(t, `<root><item id="1">a</item></root>`),
+		newDocumentFromString(t, `<root><item id="1">a</item></root>`),
+		DefaultDiffOptions(),
+	)
+	if err != nil {
+		t.Fatal(err)
+	}
+	checkIntEq(t, len(ops), 0)
+}
+
+func TestDiffAttributeChange(t *testing.T) {
+	ops, err := Diff(
+		newDocumentFromString(t, `<root><item id="1" lang="en">a</item></root>`),
+		newDocumentFromString(t, `<root><item id="1" lang="fr">a</item></root>`),
+		DefaultDiffOptions(),
+	)
+	if err != nil {
+		t.Fatal(err)
+	}
+	checkIntEq(t, len(ops), 1)
+	checkStrEq(t, ops[0].Type.String(), "update-attr")
+	checkStrEq(t, ops[0].Path, "/root/item[1]")
+	checkStrEq(t, ops[0].AttrName, "lang")
+	checkStrEq(t, ops[0].OldValue.(string), "en")
+	checkStrEq(t, ops[0].NewValue.(string), "fr")
+}
+
+func TestDiffAttributeAddAndRemove(t *testing.T) {
+	ops, err := Diff(
+		newDocumentFromString(t, `<root><item id="1" gone="1">a</item></root>`),
+		newDocumentFromString(t, `<root><item id="1" added="2">a</item></root>`),
+		DefaultDiffOptions(),
+	)
+	if err != nil {
+		t.Fatal(err)
+	}
+	checkIntEq(t, len(ops), 2)
+
+	// removed attribute first (base order), then added attribute
+	checkStrEq(t, ops[0].Type.String(), "remove")
+	checkStrEq(t, ops[0].Path, "/root/item[1]")
+	checkStrEq(t, ops[0].AttrName, "gone")
+	checkBoolEq(t, ops[1].Type == OpUpdateAttr, true)
+	checkBoolEq(t, ops[1].OldValue == nil, true)
+	checkStrEq(t, ops[1].AttrName, "added")
+	checkStrEq(t, ops[1].NewValue.(string), "2")
