+	patch = newDocumentFromString(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><replace sel="/root/item[1]/@lang">fr</replace></diff>`)
+	if err := doc.Patch(patch); err != nil {
+		t.Fatal(err)
+	}
+	checkStrEq(t, doc.WriteToStringNoHeader(t), `<root><item id="1" lang="fr">a</item></root>`)
+
+	// replace text
+	doc = newDocumentFromString(t, `<root><item id="1">a</item></root>`)
+	patch = newDocumentFromString(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><replace sel="/root/item[1]/text()">b</replace></diff>`)
+	if err := doc.Patch(patch); err != nil {
+		t.Fatal(err)
+	}
+	checkStrEq(t, doc.WriteToStringNoHeader(t), `<root><item id="1">b</item></root>`)
+
+	// remove element
+	doc = newDocumentFromString(t, `<root><item id="1">a</item><item id="2">b</item></root>`)
+	patch = newDocumentFromString(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove sel="/root/item[1]"/></diff>`)
+	if err := doc.Patch(patch); err != nil {
+		t.Fatal(err)
+	}
+	checkStrEq(t, doc.WriteToStringNoHeader(t), `<root><item id="2">b</item></root>`)
+
+	// remove attribute
+	doc = newDocumentFromString(t, `<root><item id="1" lang="en">a</item></root>`)
+	patch = newDocumentFromString(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove sel="/root/item[1]/@lang"/></diff>`)
+	if err := doc.Patch(patch); err != nil {
+		t.Fatal(err)
+	}
+	checkStrEq(t, doc.WriteToStringNoHeader(t), `<root><item id="1">a</item></root>`)
+
+	// remove text
+	doc = newDocumentFromString(t, `<root><item id="1">a</item></root>`)
+	patch = newDocumentFromString(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><remove sel="/root/item[1]/text()"/></diff>`)
+	if err := doc.Patch(patch); err != nil {
+		t.Fatal(err)
+	}
+	checkStrEq(t, doc.WriteToStringNoHeader(t), `<root><item id="1"/></root>`)
+
+	// replace element
+	doc = newDocumentFromString(t, `<root><item id="1">a</item></root>`)
+	patch = newDocumentFromString(t, `<diff xmlns="urn:ietf:params:xml:ns:patch-ops"><replace sel="/root/item[1]"><other id="9">z</other></replace></diff>`)
