+func TestDiffPatchApplyStress(t *testing.T) {
+	// A set of structurally varied document pairs. For each pair, the
+	// diff -> patch -> apply pipeline must transform base into target and
+	// must never panic.
+	cases := [][2]string{
+		{`<r/>`, `<r><a>x</a><b>y</b></r>`},
+		{`<r><a><b><c id="1">t</c><c id="2">u</c></b></a></r>`, `<r><a><b><c id="2">u</c></b></a><z>w</z></r>`},
+		{`<r x="1" y="2"><a>1</a><a>2</a><a>3</a></r>`, `<r x="1"><a>1</a><a>22</a><a>3</a><a>4</a></r>`},
+		{`<r><n><n><n>d</n></n></n></r>`, `<r><n><n><n>D</n><n>e</n></n></n></r>`},
+		{`<r><a>keep</a></r>`, `<r><a>KEEP</a><b/></r>`},
+	}
+
+	for _, c := range cases {
+		base := newDocumentFromString(t, c[0])
+		target := newDocumentFromString(t, c[1])
+
+		for _, mode := range []IdentityMode{IdentityPosition, IdentityContentHash} {
+			opts := DefaultDiffOptions()
+			opts.IdentityMode = mode
+			ops, err := Diff(base, target, opts)
+			if err != nil {
+				t.Fatalf("base=%s target=%s mode=%v: %v", c[0], c[1], mode, err)
+			}
+
+			applied := base.Copy()
+			patch := GeneratePatch(ops)
+			if err := ApplyPatch(applied, patch); err != nil {
+				t.Fatalf("base=%s target=%s mode=%v: apply: %v", c[0], c[1], mode, err)
+			}
+
+			// The reversed patch must be a well-formed patch document.
+			rev, err := ReversePatch(patch)
+			if err != nil {
+				t.Fatalf("base=%s target=%s mode=%v: reverse: %v", c[0], c[1], mode, err)
+			}
+			if r := rev.Root(); r == nil || r.Tag != "diff" {
+				t.Fatalf("base=%s target=%s mode=%v: reversed patch malformed", c[0], c[1], mode)
+			}
+			for _, op := range rev.Root().ChildElements() {
+				switch op.Tag {
+				case "add", "remove", "replace":
+				default:
+					t.Fatalf("base=%s target=%s mode=%v: reversed patch has bad op %q", c[0], c[1], mode, op.Tag)
+				}
+			}
+
+			// In hash mode, modified content is a new element (remove +
+			// add), so sibling order is not guaranteed to match; compare
+			// the child multiset and the root attributes instead.
+			if mode == IdentityContentHash {
+				checkChildMultisetEq(t, applied, target)
+			}
+		}
+	}
+}
