+</catalog>`
+	ours := `<catalog>
+  <book id="1"><title>T1-new</title><price>1</price></book>
+  <book id="2"><title>T2</title><price>20</price></book>
+  <book id="3"><title>T3</title><price>3</price></book>
+  <book id="4"><title>T4</title><price>4</price></book>
+</catalog>`
+	theirs := `<catalog>
+  <book id="1"><title>T1</title><price>1</price></book>
+  <book id="2"><title>T2</title><price>2</price></book>
+  <book id="3"><title>T3-new</title><price>33</price></book>
+</catalog>`
+
+	baseDoc := newDocumentFromString(t, base)
+	oursDoc := newDocumentFromString(t, ours)
+	theirsDoc := newDocumentFromString(t, theirs)
+
+	merged, conflicts, err := Merge3Way(baseDoc, oursDoc, theirsDoc, DefaultMergeOptions())
+	if err != nil {
+		t.Fatal(err)
+	}
+	checkIntEq(t, len(conflicts), 0)
+	got, _ := merged.WriteToString()
+	// compare ignoring insignificant whitespace
+	checkStrEq(t, normalizeXML(t, got), normalizeXML(t, `<catalog>`+
+		`<book id="1"><title>T1-new</title><price>1</price></book>`+
+		`<book id="2"><title>T2</title><price>20</price></book>`+
+		`<book id="3"><title>T3-new</title><price>33</price></book>`+
+		`<book id="4"><title>T4</title><price>4</price></book>`+
+		`</catalog>`))
+	checkStrEq(t, merged.Metadata["merge.base"], "catalog")
+}
+
+// normalizeXML removes insignificant whitespace (text that is only
+// whitespace between elements) from a serialized document for comparison.
+func normalizeXML(t *testing.T, s string) string {
+	t.Helper()
+	doc := NewDocument()
+	if err := doc.ReadFromString(s); err != nil {
+		t.Fatal(err)
+	}
+	var strip func(e *Element)
+	strip = func(e *Element) {
+		kept := e.Child[:0]
+		for _, c := range e.Child {
+			switch c := c.(type) {
+			case *CharData:
+				if !isWhitespace(c.Data) {
+					kept = append(kept, c)
+				}
+			case *Element:
+				strip(c)
+				kept = append(kept, c)
+			default:
+				kept = append(kept, c)
+			}
+		}
+		e.Child = kept
+	}
+	if r := doc.Root(); r != nil {
+		strip(r)
+	}
+	out, err := doc.WriteToString()
+	if err != nil {
+		t.Fatal(err)
+	}
+	return out
+}
+
+// checkChildMultisetEq compares the root attributes and the multiset of
+// child subtree hashes of two documents.
+func checkChildMultisetEq(t *testing.T, a, b *Document) {
+	t.Helper()
+	ra, rb := a.Root(), b.Root()
+	checkBoolEq(t, ra.Tag == rb.Tag, true)
+	checkBoolEq(t, attrsDeepEqual(ra.Attr, rb.Attr), true)
+	checkStrEq(t, ra.Text(), rb.Text())
+
+	hashes := func(r *Element) []string {
+		var hs []string
+		for _, c := range r.ChildElements() {
+			hs = append(hs, contentHash(c, DefaultDiffOptions()))
+		}
+		sort.Strings(hs)
+		return hs
+	}
+	ha, hb := hashes(ra), hashes(rb)
+	checkIntEq(t, len(ha), len(hb))
+	for i := range ha {
+		checkStrEq(t, ha[i], hb[i])
+	}
+}
